// Business & work-relatable Bible verses (World English Bible, public domain)
// 1,095 verses = 3 per day for a full year.

export interface BibleVerse {
  text: string;
  reference: string;
}

export const businessBibleVerses: BibleVerse[] = [
  { text: "The proverbs of Solomon, the son of David, king of Israel:", reference: "Proverbs 1:1" },
  { text: "to know wisdom and instruction; to discern the words of understanding;", reference: "Proverbs 1:2" },
  { text: "to receive instruction in wise dealing, in righteousness, justice, and equity;", reference: "Proverbs 1:3" },
  { text: "to give prudence to the simple, knowledge and discretion to the young man:", reference: "Proverbs 1:4" },
  { text: "that the wise man may hear, and increase in learning; that the man of understanding may attain to sound counsel:", reference: "Proverbs 1:5" },
  { text: "to understand a proverb, and parables, the words and riddles of the wise.", reference: "Proverbs 1:6" },
  { text: "The fear of Yahweh is the beginning of knowledge; but the foolish despise wisdom and instruction.", reference: "Proverbs 1:7" },
  { text: "My son, listen to your father’s instruction, and don’t forsake your mother’s teaching:", reference: "Proverbs 1:8" },
  { text: "for they will be a garland to grace your head, and chains around your neck.", reference: "Proverbs 1:9" },
  { text: "My son, if sinners entice you, don’t consent.", reference: "Proverbs 1:10" },
  { text: "If they say, “Come with us. Let’s lay in wait for blood. Let’s lurk secretly for the innocent without cause.", reference: "Proverbs 1:11" },
  { text: "Let’s swallow them up alive like Sheol, and whole, like those who go down into the pit.", reference: "Proverbs 1:12" },
  { text: "We’ll find all valuable wealth. We’ll fill our houses with plunder.", reference: "Proverbs 1:13" },
  { text: "You shall cast your lot among us. We’ll all have one purse.”", reference: "Proverbs 1:14" },
  { text: "My son, don’t walk on the path with them. Keep your foot from their path,", reference: "Proverbs 1:15" },
  { text: "for their feet run to evil. They hurry to shed blood.", reference: "Proverbs 1:16" },
  { text: "For in vain is the net spread in the sight of any bird:", reference: "Proverbs 1:17" },
  { text: "but these lay wait for their own blood. They lurk secretly for their own lives.", reference: "Proverbs 1:18" },
  { text: "So are the ways of everyone who is greedy for gain. It takes away the life of its owners.", reference: "Proverbs 1:19" },
  { text: "Wisdom calls aloud in the street. She utters her voice in the public squares.", reference: "Proverbs 1:20" },
  { text: "She calls at the head of noisy places. At the entrance of the city gates, she utters her words:", reference: "Proverbs 1:21" },
  { text: "“How long, you simple ones, will you love simplicity? How long will mockers delight themselves in mockery, and fools hate knowledge?", reference: "Proverbs 1:22" },
  { text: "Turn at my reproof. Behold, I will pour out my spirit on you. I will make known my words to you.", reference: "Proverbs 1:23" },
  { text: "Because I have called, and you have refused; I have stretched out my hand, and no one has paid attention;", reference: "Proverbs 1:24" },
  { text: "but you have ignored all my counsel, and wanted none of my reproof;", reference: "Proverbs 1:25" },
  { text: "I also will laugh at your disaster. I will mock when calamity overtakes you;", reference: "Proverbs 1:26" },
  { text: "when calamity overtakes you like a storm, when your disaster comes on like a whirlwind; when distress and anguish come on you.", reference: "Proverbs 1:27" },
  { text: "Then will they call on me, but I will not answer. They will seek me diligently, but they will not find me;", reference: "Proverbs 1:28" },
  { text: "because they hated knowledge, and didn’t choose the fear of Yahweh.", reference: "Proverbs 1:29" },
  { text: "They wanted none of my counsel. They despised all my reproof.", reference: "Proverbs 1:30" },
  { text: "Therefore they will eat of the fruit of their own way, and be filled with their own schemes.", reference: "Proverbs 1:31" },
  { text: "For the backsliding of the simple will kill them. The careless ease of fools will destroy them.", reference: "Proverbs 1:32" },
  { text: "But whoever listens to me will dwell securely, and will be at ease, without fear of harm.”", reference: "Proverbs 1:33" },
  { text: "My son, if you will receive my words, and store up my commandments within you;", reference: "Proverbs 2:1" },
  { text: "So as to turn your ear to wisdom, and apply your heart to understanding;", reference: "Proverbs 2:2" },
  { text: "Yes, if you call out for discernment, and lift up your voice for understanding;", reference: "Proverbs 2:3" },
  { text: "If you seek her as silver, and search for her as for hidden treasures:", reference: "Proverbs 2:4" },
  { text: "then you will understand the fear of Yahweh, and find the knowledge of God.", reference: "Proverbs 2:5" },
  { text: "For Yahweh gives wisdom. Out of his mouth comes knowledge and understanding.", reference: "Proverbs 2:6" },
  { text: "He lays up sound wisdom for the upright. He is a shield to those who walk in integrity;", reference: "Proverbs 2:7" },
  { text: "that he may guard the paths of justice, and preserve the way of his saints.", reference: "Proverbs 2:8" },
  { text: "Then you will understand righteousness and justice, equity and every good path.", reference: "Proverbs 2:9" },
  { text: "For wisdom will enter into your heart. Knowledge will be pleasant to your soul.", reference: "Proverbs 2:10" },
  { text: "Discretion will watch over you. Understanding will keep you,", reference: "Proverbs 2:11" },
  { text: "to deliver you from the way of evil, from the men who speak perverse things;", reference: "Proverbs 2:12" },
  { text: "who forsake the paths of uprightness, to walk in the ways of darkness;", reference: "Proverbs 2:13" },
  { text: "who rejoice to do evil, and delight in the perverseness of evil;", reference: "Proverbs 2:14" },
  { text: "who are crooked in their ways, and wayward in their paths:", reference: "Proverbs 2:15" },
  { text: "To deliver you from the strange woman, even from the foreigner who flatters with her words;", reference: "Proverbs 2:16" },
  { text: "who forsakes the friend of her youth, and forgets the covenant of her God:", reference: "Proverbs 2:17" },
  { text: "for her house leads down to death, her paths to the departed spirits.", reference: "Proverbs 2:18" },
  { text: "None who go to her return again, neither do they attain to the paths of life:", reference: "Proverbs 2:19" },
  { text: "that you may walk in the way of good men, and keep the paths of the righteous.", reference: "Proverbs 2:20" },
  { text: "For the upright will dwell in the land. The perfect will remain in it.", reference: "Proverbs 2:21" },
  { text: "But the wicked will be cut off from the land. The treacherous will be rooted out of it.", reference: "Proverbs 2:22" },
  { text: "My son, don’t forget my teaching; but let your heart keep my commandments:", reference: "Proverbs 3:1" },
  { text: "for length of days, and years of life, and peace, will they add to you.", reference: "Proverbs 3:2" },
  { text: "Don’t let kindness and truth forsake you. Bind them around your neck. Write them on the tablet of your heart.", reference: "Proverbs 3:3" },
  { text: "So you will find favor, and good understanding in the sight of God and man.", reference: "Proverbs 3:4" },
  { text: "Trust in Yahweh with all your heart, and don’t lean on your own understanding.", reference: "Proverbs 3:5" },
  { text: "In all your ways acknowledge him, and he will make your paths straight.", reference: "Proverbs 3:6" },
  { text: "Don’t be wise in your own eyes. Fear Yahweh, and depart from evil.", reference: "Proverbs 3:7" },
  { text: "It will be health to your body, and nourishment to your bones.", reference: "Proverbs 3:8" },
  { text: "Honor Yahweh with your substance, with the first fruits of all your increase:", reference: "Proverbs 3:9" },
  { text: "so your barns will be filled with plenty, and your vats will overflow with new wine.", reference: "Proverbs 3:10" },
  { text: "My son, don’t despise Yahweh’s discipline, neither be weary of his reproof:", reference: "Proverbs 3:11" },
  { text: "for whom Yahweh loves, he reproves; even as a father reproves the son in whom he delights.", reference: "Proverbs 3:12" },
  { text: "Happy is the man who finds wisdom, the man who gets understanding.", reference: "Proverbs 3:13" },
  { text: "For her good profit is better than getting silver, and her return is better than fine gold.", reference: "Proverbs 3:14" },
  { text: "She is more precious than rubies. None of the things you can desire are to be compared to her.", reference: "Proverbs 3:15" },
  { text: "Length of days is in her right hand. In her left hand are riches and honor.", reference: "Proverbs 3:16" },
  { text: "Her ways are ways of pleasantness. All her paths are peace.", reference: "Proverbs 3:17" },
  { text: "She is a tree of life to those who lay hold of her. Happy is everyone who retains her.", reference: "Proverbs 3:18" },
  { text: "By wisdom Yahweh founded the earth. By understanding, he established the heavens.", reference: "Proverbs 3:19" },
  { text: "By his knowledge, the depths were broken up, and the skies drop down the dew.", reference: "Proverbs 3:20" },
  { text: "My son, let them not depart from your eyes. Keep sound wisdom and discretion:", reference: "Proverbs 3:21" },
  { text: "so they will be life to your soul, and grace for your neck.", reference: "Proverbs 3:22" },
  { text: "Then you shall walk in your way securely. Your foot won’t stumble.", reference: "Proverbs 3:23" },
  { text: "When you lie down, you will not be afraid. Yes, you will lie down, and your sleep will be sweet.", reference: "Proverbs 3:24" },
  { text: "Don’t be afraid of sudden fear, neither of the desolation of the wicked, when it comes:", reference: "Proverbs 3:25" },
  { text: "for Yahweh will be your confidence, and will keep your foot from being taken.", reference: "Proverbs 3:26" },
  { text: "Don’t withhold good from those to whom it is due, when it is in the power of your hand to do it.", reference: "Proverbs 3:27" },
  { text: "Don’t say to your neighbor, “Go, and come again; tomorrow I will give it to you,” when you have it by you.", reference: "Proverbs 3:28" },
  { text: "Don’t devise evil against your neighbor, since he dwells securely by you.", reference: "Proverbs 3:29" },
  { text: "Don’t strive with a man without cause, if he has done you no harm.", reference: "Proverbs 3:30" },
  { text: "Don’t envy the man of violence. Choose none of his ways.", reference: "Proverbs 3:31" },
  { text: "For the perverse is an abomination to Yahweh, but his friendship is with the upright.", reference: "Proverbs 3:32" },
  { text: "Yahweh’s curse is in the house of the wicked, but he blesses the habitation of the righteous.", reference: "Proverbs 3:33" },
  { text: "Surely he mocks the mockers, but he gives grace to the humble.", reference: "Proverbs 3:34" },
  { text: "The wise will inherit glory, but shame will be the promotion of fools.", reference: "Proverbs 3:35" },
  { text: "Listen, sons, to a father’s instruction. Pay attention and know understanding;", reference: "Proverbs 4:1" },
  { text: "for I give you sound learning. Don’t forsake my law.", reference: "Proverbs 4:2" },
  { text: "For I was a son to my father, tender and an only child in the sight of my mother.", reference: "Proverbs 4:3" },
  { text: "He taught me, and said to me: “Let your heart retain my words. Keep my commandments, and live.", reference: "Proverbs 4:4" },
  { text: "Get wisdom. Get understanding. Don’t forget, and don’t deviate from the words of my mouth.", reference: "Proverbs 4:5" },
  { text: "Don’t forsake her, and she will preserve you. Love her, and she will keep you.", reference: "Proverbs 4:6" },
  { text: "Wisdom is supreme. Get wisdom. Yes, though it costs all your possessions, get understanding.", reference: "Proverbs 4:7" },
  { text: "Esteem her, and she will exalt you. She will bring you to honor, when you embrace her.", reference: "Proverbs 4:8" },
  { text: "She will give to your head a garland of grace. She will deliver a crown of splendor to you.”", reference: "Proverbs 4:9" },
  { text: "Listen, my son, and receive my sayings. The years of your life will be many.", reference: "Proverbs 4:10" },
  { text: "I have taught you in the way of wisdom. I have led you in straight paths.", reference: "Proverbs 4:11" },
  { text: "When you go, your steps will not be hampered. When you run, you will not stumble.", reference: "Proverbs 4:12" },
  { text: "Take firm hold of instruction. Don’t let her go. Keep her, for she is your life.", reference: "Proverbs 4:13" },
  { text: "Don’t enter into the path of the wicked. Don’t walk in the way of evil men.", reference: "Proverbs 4:14" },
  { text: "Avoid it, and don’t pass by it. Turn from it, and pass on.", reference: "Proverbs 4:15" },
  { text: "For they don’t sleep, unless they do evil. Their sleep is taken away, unless they make someone fall.", reference: "Proverbs 4:16" },
  { text: "For they eat the bread of wickedness, and drink the wine of violence.", reference: "Proverbs 4:17" },
  { text: "But the path of the righteous is like the dawning light, that shines more and more until the perfect day.", reference: "Proverbs 4:18" },
  { text: "The way of the wicked is like darkness. They don’t know what they stumble over.", reference: "Proverbs 4:19" },
  { text: "My son, attend to my words. Turn your ear to my sayings.", reference: "Proverbs 4:20" },
  { text: "Let them not depart from your eyes. Keep them in the center of your heart.", reference: "Proverbs 4:21" },
  { text: "For they are life to those who find them, and health to their whole body.", reference: "Proverbs 4:22" },
  { text: "Keep your heart with all diligence, for out of it is the wellspring of life.", reference: "Proverbs 4:23" },
  { text: "Put away from yourself a perverse mouth. Put corrupt lips far from you.", reference: "Proverbs 4:24" },
  { text: "Let your eyes look straight ahead. Fix your gaze directly before you.", reference: "Proverbs 4:25" },
  { text: "Make the path of your feet level. Let all of your ways be established.", reference: "Proverbs 4:26" },
  { text: "Don’t turn to the right hand nor to the left. Remove your foot from evil.", reference: "Proverbs 4:27" },
  { text: "My son, pay attention to my wisdom. Turn your ear to my understanding:", reference: "Proverbs 5:1" },
  { text: "that you may maintain discretion, that your lips may preserve knowledge.", reference: "Proverbs 5:2" },
  { text: "For the lips of an adulteress drip honey. Her mouth is smoother than oil,", reference: "Proverbs 5:3" },
  { text: "but in the end she is as bitter as wormwood, and as sharp as a two-edged sword.", reference: "Proverbs 5:4" },
  { text: "Her feet go down to death. Her steps lead straight to Sheol.", reference: "Proverbs 5:5" },
  { text: "She gives no thought to the way of life. Her ways are crooked, and she doesn’t know it.", reference: "Proverbs 5:6" },
  { text: "Now therefore, my sons, listen to me. Don’t depart from the words of my mouth.", reference: "Proverbs 5:7" },
  { text: "Remove your way far from her. Don’t come near the door of her house,", reference: "Proverbs 5:8" },
  { text: "lest you give your honor to others, and your years to the cruel one;", reference: "Proverbs 5:9" },
  { text: "lest strangers feast on your wealth, and your labors enrich another man’s house.", reference: "Proverbs 5:10" },
  { text: "You will groan at your latter end, when your flesh and your body are consumed,", reference: "Proverbs 5:11" },
  { text: "and say, “How I have hated instruction, and my heart despised reproof;", reference: "Proverbs 5:12" },
  { text: "neither have I obeyed the voice of my teachers, nor turned my ear to those who instructed me!", reference: "Proverbs 5:13" },
  { text: "I have come to the brink of utter ruin, among the gathered assembly.”", reference: "Proverbs 5:14" },
  { text: "Drink water out of your own cistern, running water out of your own well.", reference: "Proverbs 5:15" },
  { text: "Should your springs overflow in the streets, streams of water in the public squares?", reference: "Proverbs 5:16" },
  { text: "Let them be for yourself alone, not for strangers with you.", reference: "Proverbs 5:17" },
  { text: "Let your spring be blessed. Rejoice in the wife of your youth.", reference: "Proverbs 5:18" },
  { text: "A loving doe and a graceful deer— let her breasts satisfy you at all times. Be captivated always with her love.", reference: "Proverbs 5:19" },
  { text: "For why should you, my son, be captivated with an adulteress? Why embrace the bosom of another?", reference: "Proverbs 5:20" },
  { text: "For the ways of man are before Yahweh’s eyes. He examines all his paths.", reference: "Proverbs 5:21" },
  { text: "The evil deeds of the wicked ensnare him. The cords of his sin hold him firmly.", reference: "Proverbs 5:22" },
  { text: "He will die for lack of instruction. In the greatness of his folly, he will go astray.", reference: "Proverbs 5:23" },
  { text: "My son, if you have become collateral for your neighbor, if you have struck your hands in pledge for a stranger;", reference: "Proverbs 6:1" },
  { text: "You are trapped by the words of your mouth. You are ensnared with the words of your mouth.", reference: "Proverbs 6:2" },
  { text: "Do this now, my son, and deliver yourself, since you have come into the hand of your neighbor. Go, humble yourself. Press your plea with your neighbor.", reference: "Proverbs 6:3" },
  { text: "Give no sleep to your eyes, nor slumber to your eyelids.", reference: "Proverbs 6:4" },
  { text: "Free yourself, like a gazelle from the hand of the hunter, like a bird from the snare of the fowler.", reference: "Proverbs 6:5" },
  { text: "Go to the ant, you sluggard. Consider her ways, and be wise;", reference: "Proverbs 6:6" },
  { text: "provides her bread in the summer, and gathers her food in the harvest.", reference: "Proverbs 6:8" },
  { text: "How long will you sleep, sluggard? When will you arise out of your sleep?", reference: "Proverbs 6:9" },
  { text: "A little sleep, a little slumber, a little folding of the hands to sleep:", reference: "Proverbs 6:10" },
  { text: "so your poverty will come as a robber, and your scarcity as an armed man.", reference: "Proverbs 6:11" },
  { text: "A worthless person, a man of iniquity, is he who walks with a perverse mouth;", reference: "Proverbs 6:12" },
  { text: "who winks with his eyes, who signals with his feet, who motions with his fingers;", reference: "Proverbs 6:13" },
  { text: "in whose heart is perverseness, who devises evil continually, who always sows discord.", reference: "Proverbs 6:14" },
  { text: "Therefore his calamity will come suddenly. He will be broken suddenly, and that without remedy.", reference: "Proverbs 6:15" },
  { text: "There are six things which Yahweh hates; yes, seven which are an abomination to him:", reference: "Proverbs 6:16" },
  { text: "haughty eyes, a lying tongue, hands that shed innocent blood;", reference: "Proverbs 6:17" },
  { text: "a heart that devises wicked schemes, feet that are swift in running to mischief,", reference: "Proverbs 6:18" },
  { text: "a false witness who utters lies, and he who sows discord among brothers.", reference: "Proverbs 6:19" },
  { text: "My son, keep your father’s commandment, and don’t forsake your mother’s teaching.", reference: "Proverbs 6:20" },
  { text: "Bind them continually on your heart. Tie them around your neck.", reference: "Proverbs 6:21" },
  { text: "When you walk, it will lead you. When you sleep, it will watch over you. When you awake, it will talk with you.", reference: "Proverbs 6:22" },
  { text: "For the commandment is a lamp, and the law is light. Reproofs of instruction are the way of life,", reference: "Proverbs 6:23" },
  { text: "to keep you from the immoral woman, from the flattery of the wayward wife’s tongue.", reference: "Proverbs 6:24" },
  { text: "Don’t lust after her beauty in your heart, neither let her captivate you with her eyelids.", reference: "Proverbs 6:25" },
  { text: "For a prostitute reduces you to a piece of bread. The adulteress hunts for your precious life.", reference: "Proverbs 6:26" },
  { text: "Can a man scoop fire into his lap, and his clothes not be burned?", reference: "Proverbs 6:27" },
  { text: "Or can one walk on hot coals, and his feet not be scorched?", reference: "Proverbs 6:28" },
  { text: "So is he who goes in to his neighbor’s wife. Whoever touches her will not be unpunished.", reference: "Proverbs 6:29" },
  { text: "Men don’t despise a thief, if he steals to satisfy himself when he is hungry:", reference: "Proverbs 6:30" },
  { text: "but if he is found, he shall restore seven times. He shall give all the wealth of his house.", reference: "Proverbs 6:31" },
  { text: "He who commits adultery with a woman is void of understanding. He who does it destroys his own soul.", reference: "Proverbs 6:32" },
  { text: "He will get wounds and dishonor. His reproach will not be wiped away.", reference: "Proverbs 6:33" },
  { text: "For jealousy arouses the fury of the husband. He won’t spare in the day of vengeance.", reference: "Proverbs 6:34" },
  { text: "He won’t regard any ransom, neither will he rest content, though you give many gifts.", reference: "Proverbs 6:35" },
  { text: "My son, keep my words. Lay up my commandments within you.", reference: "Proverbs 7:1" },
  { text: "Keep my commandments and live! Guard my teaching as the apple of your eye.", reference: "Proverbs 7:2" },
  { text: "Bind them on your fingers. Write them on the tablet of your heart.", reference: "Proverbs 7:3" },
  { text: "Tell wisdom, “You are my sister.” Call understanding your relative,", reference: "Proverbs 7:4" },
  { text: "that they may keep you from the strange woman, from the foreigner who flatters with her words.", reference: "Proverbs 7:5" },
  { text: "For at the window of my house, I looked out through my lattice.", reference: "Proverbs 7:6" },
  { text: "I saw among the simple ones. I discerned among the youths a young man void of understanding,", reference: "Proverbs 7:7" },
  { text: "passing through the street near her corner, he went the way to her house,", reference: "Proverbs 7:8" },
  { text: "in the twilight, in the evening of the day, in the middle of the night and in the darkness.", reference: "Proverbs 7:9" },
  { text: "Behold, there a woman met him with the attire of a prostitute, and with crafty intent.", reference: "Proverbs 7:10" },
  { text: "She is loud and defiant. Her feet don’t stay in her house.", reference: "Proverbs 7:11" },
  { text: "Now she is in the streets, now in the squares, and lurking at every corner.", reference: "Proverbs 7:12" },
  { text: "So she caught him, and kissed him. With an impudent face she said to him:", reference: "Proverbs 7:13" },
  { text: "“Sacrifices of peace offerings are with me. Today I have paid my vows.", reference: "Proverbs 7:14" },
  { text: "Therefore I came out to meet you, to diligently seek your face, and I have found you.", reference: "Proverbs 7:15" },
  { text: "I have spread my couch with carpets of tapestry, with striped cloths of the yarn of Egypt.", reference: "Proverbs 7:16" },
  { text: "I have perfumed my bed with myrrh, aloes, and cinnamon.", reference: "Proverbs 7:17" },
  { text: "Come, let’s take our fill of loving until the morning. Let’s solace ourselves with loving.", reference: "Proverbs 7:18" },
  { text: "For my husband isn’t at home. He has gone on a long journey.", reference: "Proverbs 7:19" },
  { text: "He has taken a bag of money with him. He will come home at the full moon.”", reference: "Proverbs 7:20" },
  { text: "With persuasive words, she led him astray. With the flattering of her lips, she seduced him.", reference: "Proverbs 7:21" },
  { text: "He followed her immediately, as an ox goes to the slaughter, as a fool stepping into a noose.", reference: "Proverbs 7:22" },
  { text: "Until an arrow strikes through his liver, as a bird hurries to the snare, and doesn’t know that it will cost his life.", reference: "Proverbs 7:23" },
  { text: "Now therefore, sons, listen to me. Pay attention to the words of my mouth.", reference: "Proverbs 7:24" },
  { text: "Don’t let your heart turn to her ways. Don’t go astray in her paths,", reference: "Proverbs 7:25" },
  { text: "for she has thrown down many wounded. Yes, all her slain are a mighty army.", reference: "Proverbs 7:26" },
  { text: "Her house is the way to Sheol, going down to the rooms of death.", reference: "Proverbs 7:27" },
  { text: "Doesn’t wisdom cry out? Doesn’t understanding raise her voice?", reference: "Proverbs 8:1" },
  { text: "On the top of high places by the way, where the paths meet, she stands.", reference: "Proverbs 8:2" },
  { text: "Beside the gates, at the entry of the city, at the entry doors, she cries aloud:", reference: "Proverbs 8:3" },
  { text: "“To you men, I call! I send my voice to the sons of mankind.", reference: "Proverbs 8:4" },
  { text: "You simple, understand prudence. You fools, be of an understanding heart.", reference: "Proverbs 8:5" },
  { text: "Hear, for I will speak excellent things. The opening of my lips is for right things.", reference: "Proverbs 8:6" },
  { text: "For my mouth speaks truth. Wickedness is an abomination to my lips.", reference: "Proverbs 8:7" },
  { text: "All the words of my mouth are in righteousness. There is nothing crooked or perverse in them.", reference: "Proverbs 8:8" },
  { text: "They are all plain to him who understands, right to those who find knowledge.", reference: "Proverbs 8:9" },
  { text: "Receive my instruction rather than silver; knowledge rather than choice gold.", reference: "Proverbs 8:10" },
  { text: "For wisdom is better than rubies. All the things that may be desired can’t be compared to it.", reference: "Proverbs 8:11" },
  { text: "“I, wisdom, have made prudence my dwelling. Find out knowledge and discretion.", reference: "Proverbs 8:12" },
  { text: "The fear of Yahweh is to hate evil. I hate pride, arrogance, the evil way, and the perverse mouth.", reference: "Proverbs 8:13" },
  { text: "Counsel and sound knowledge are mine. I have understanding and power.", reference: "Proverbs 8:14" },
  { text: "By me kings reign, and princes decree justice.", reference: "Proverbs 8:15" },
  { text: "By me princes rule; nobles, and all the righteous rulers of the earth.", reference: "Proverbs 8:16" },
  { text: "I love those who love me. Those who seek me diligently will find me.", reference: "Proverbs 8:17" },
  { text: "With me are riches, honor, enduring wealth, and prosperity.", reference: "Proverbs 8:18" },
  { text: "My fruit is better than gold, yes, than fine gold; my yield than choice silver.", reference: "Proverbs 8:19" },
  { text: "I walk in the way of righteousness, in the middle of the paths of justice;", reference: "Proverbs 8:20" },
  { text: "that I may give wealth to those who love me. I fill their treasuries.", reference: "Proverbs 8:21" },
  { text: "“Yahweh possessed me in the beginning of his work, before his deeds of old.", reference: "Proverbs 8:22" },
  { text: "I was set up from everlasting, from the beginning, before the earth existed.", reference: "Proverbs 8:23" },
  { text: "When there were no depths, I was born, when there were no springs abounding with water.", reference: "Proverbs 8:24" },
  { text: "Before the mountains were settled in place, before the hills, I was born;", reference: "Proverbs 8:25" },
  { text: "while as yet he had not made the earth, nor the fields, nor the beginning of the dust of the world.", reference: "Proverbs 8:26" },
  { text: "When he established the heavens, I was there; when he set a circle on the surface of the deep,", reference: "Proverbs 8:27" },
  { text: "when he established the clouds above, when the springs of the deep became strong,", reference: "Proverbs 8:28" },
  { text: "when he gave to the sea its boundary, that the waters should not violate his commandment, when he marked out the foundations of the earth;", reference: "Proverbs 8:29" },
  { text: "then I was the craftsman by his side. I was a delight day by day, always rejoicing before him,", reference: "Proverbs 8:30" },
  { text: "rejoicing in his whole world. My delight was with the sons of men.", reference: "Proverbs 8:31" },
  { text: "“Now therefore, my sons, listen to me, for blessed are those who keep my ways.", reference: "Proverbs 8:32" },
  { text: "Hear instruction, and be wise. Don’t refuse it.", reference: "Proverbs 8:33" },
  { text: "Blessed is the man who hears me, watching daily at my gates, waiting at my door posts.", reference: "Proverbs 8:34" },
  { text: "For whoever finds me, finds life, and will obtain favor from Yahweh.", reference: "Proverbs 8:35" },
  { text: "But he who sins against me wrongs his own soul. All those who hate me love death.”", reference: "Proverbs 8:36" },
  { text: "Wisdom has built her house. She has carved out her seven pillars.", reference: "Proverbs 9:1" },
  { text: "She has prepared her meat. She has mixed her wine. She has also set her table.", reference: "Proverbs 9:2" },
  { text: "She has sent out her maidens. She cries from the highest places of the city:", reference: "Proverbs 9:3" },
  { text: "“Whoever is simple, let him turn in here!” As for him who is void of understanding, she says to him,", reference: "Proverbs 9:4" },
  { text: "“Come, eat some of my bread, Drink some of the wine which I have mixed!", reference: "Proverbs 9:5" },
  { text: "Leave your simple ways, and live. Walk in the way of understanding.”", reference: "Proverbs 9:6" },
  { text: "He who corrects a mocker invites insult. He who reproves a wicked man invites abuse.", reference: "Proverbs 9:7" },
  { text: "Don’t reprove a scoffer, lest he hate you. Reprove a wise man, and he will love you.", reference: "Proverbs 9:8" },
  { text: "Instruct a wise man, and he will be still wiser. Teach a righteous man, and he will increase in learning.", reference: "Proverbs 9:9" },
  { text: "The fear of Yahweh is the beginning of wisdom. The knowledge of the Holy One is understanding.", reference: "Proverbs 9:10" },
  { text: "For by me your days will be multiplied. The years of your life will be increased.", reference: "Proverbs 9:11" },
  { text: "If you are wise, you are wise for yourself. If you mock, you alone will bear it.", reference: "Proverbs 9:12" },
  { text: "The foolish woman is loud, undisciplined, and knows nothing.", reference: "Proverbs 9:13" },
  { text: "She sits at the door of her house, on a seat in the high places of the city,", reference: "Proverbs 9:14" },
  { text: "To call to those who pass by, who go straight on their ways,", reference: "Proverbs 9:15" },
  { text: "“Whoever is simple, let him turn in here.” as for him who is void of understanding, she says to him,", reference: "Proverbs 9:16" },
  { text: "“Stolen water is sweet. Food eaten in secret is pleasant.”", reference: "Proverbs 9:17" },
  { text: "But he doesn’t know that the departed spirits are there, that her guests are in the depths of Sheol.", reference: "Proverbs 9:18" },
  { text: "The proverbs of Solomon. A wise son makes a glad father; but a foolish son brings grief to his mother.", reference: "Proverbs 10:1" },
  { text: "Treasures of wickedness profit nothing, but righteousness delivers from death.", reference: "Proverbs 10:2" },
  { text: "Yahweh will not allow the soul of the righteous to go hungry, but he thrusts away the desire of the wicked.", reference: "Proverbs 10:3" },
  { text: "He becomes poor who works with a lazy hand, but the hand of the diligent brings wealth.", reference: "Proverbs 10:4" },
  { text: "He who gathers in summer is a wise son, but he who sleeps during the harvest is a son who causes shame.", reference: "Proverbs 10:5" },
  { text: "Blessings are on the head of the righteous, but violence covers the mouth of the wicked.", reference: "Proverbs 10:6" },
  { text: "The memory of the righteous is blessed, but the name of the wicked will rot.", reference: "Proverbs 10:7" },
  { text: "The wise in heart accept commandments, but a chattering fool will fall.", reference: "Proverbs 10:8" },
  { text: "He who walks blamelessly walks surely, but he who perverts his ways will be found out.", reference: "Proverbs 10:9" },
  { text: "One winking with the eye causes sorrow, but a chattering fool will fall.", reference: "Proverbs 10:10" },
  { text: "The mouth of the righteous is a spring of life, but violence covers the mouth of the wicked.", reference: "Proverbs 10:11" },
  { text: "Hatred stirs up strife, but love covers all wrongs.", reference: "Proverbs 10:12" },
  { text: "Wisdom is found on the lips of him who has discernment, but a rod is for the back of him who is void of understanding.", reference: "Proverbs 10:13" },
  { text: "Wise men lay up knowledge, but the mouth of the foolish is near ruin.", reference: "Proverbs 10:14" },
  { text: "The rich man’s wealth is his strong city. The destruction of the poor is their poverty.", reference: "Proverbs 10:15" },
  { text: "The labor of the righteous leads to life. The increase of the wicked leads to sin.", reference: "Proverbs 10:16" },
  { text: "He is in the way of life who heeds correction, but he who forsakes reproof leads others astray.", reference: "Proverbs 10:17" },
  { text: "He who hides hatred has lying lips. He who utters a slander is a fool.", reference: "Proverbs 10:18" },
  { text: "In the multitude of words there is no lack of disobedience, but he who restrains his lips does wisely.", reference: "Proverbs 10:19" },
  { text: "The tongue of the righteous is like choice silver. The heart of the wicked is of little worth.", reference: "Proverbs 10:20" },
  { text: "The lips of the righteous feed many, but the foolish die for lack of understanding.", reference: "Proverbs 10:21" },
  { text: "Yahweh’s blessing brings wealth, and he adds no trouble to it.", reference: "Proverbs 10:22" },
  { text: "It is a fool’s pleasure to do wickedness, but wisdom is a man of understanding’s pleasure.", reference: "Proverbs 10:23" },
  { text: "What the wicked fear, will overtake them, but the desire of the righteous will be granted.", reference: "Proverbs 10:24" },
  { text: "When the whirlwind passes, the wicked is no more; but the righteous stand firm forever.", reference: "Proverbs 10:25" },
  { text: "As vinegar to the teeth, and as smoke to the eyes, so is the sluggard to those who send him.", reference: "Proverbs 10:26" },
  { text: "The fear of Yahweh prolongs days, but the years of the wicked shall be shortened.", reference: "Proverbs 10:27" },
  { text: "The prospect of the righteous is joy, but the hope of the wicked will perish.", reference: "Proverbs 10:28" },
  { text: "The way of Yahweh is a stronghold to the upright, but it is a destruction to the workers of iniquity.", reference: "Proverbs 10:29" },
  { text: "The righteous will never be removed, but the wicked will not dwell in the land.", reference: "Proverbs 10:30" },
  { text: "The mouth of the righteous produces wisdom, but the perverse tongue will be cut off.", reference: "Proverbs 10:31" },
  { text: "The lips of the righteous know what is acceptable, but the mouth of the wicked is perverse.", reference: "Proverbs 10:32" },
  { text: "A false balance is an abomination to Yahweh, but accurate weights are his delight.", reference: "Proverbs 11:1" },
  { text: "When pride comes, then comes shame, but with humility comes wisdom.", reference: "Proverbs 11:2" },
  { text: "The integrity of the upright shall guide them, but the perverseness of the treacherous shall destroy them.", reference: "Proverbs 11:3" },
  { text: "Riches don’t profit in the day of wrath, but righteousness delivers from death.", reference: "Proverbs 11:4" },
  { text: "The righteousness of the blameless will direct his way, but the wicked shall fall by his own wickedness.", reference: "Proverbs 11:5" },
  { text: "The righteousness of the upright shall deliver them, but the unfaithful will be trapped by evil desires.", reference: "Proverbs 11:6" },
  { text: "When a wicked man dies, hope perishes, and expectation of power comes to nothing.", reference: "Proverbs 11:7" },
  { text: "A righteous person is delivered out of trouble, and the wicked takes his place.", reference: "Proverbs 11:8" },
  { text: "With his mouth the godless man destroys his neighbor, but the righteous will be delivered through knowledge.", reference: "Proverbs 11:9" },
  { text: "When it goes well with the righteous, the city rejoices. When the wicked perish, there is shouting.", reference: "Proverbs 11:10" },
  { text: "By the blessing of the upright, the city is exalted, but it is overthrown by the mouth of the wicked.", reference: "Proverbs 11:11" },
  { text: "One who despises his neighbor is void of wisdom, but a man of understanding holds his peace.", reference: "Proverbs 11:12" },
  { text: "One who brings gossip betrays a confidence, but one who is of a trustworthy spirit is one who keeps a secret.", reference: "Proverbs 11:13" },
  { text: "Where there is no wise guidance, the nation falls, but in the multitude of counselors there is victory.", reference: "Proverbs 11:14" },
  { text: "He who is collateral for a stranger will suffer for it, but he who refuses pledges of collateral is secure.", reference: "Proverbs 11:15" },
  { text: "A gracious woman obtains honor, but violent men obtain riches.", reference: "Proverbs 11:16" },
  { text: "The merciful man does good to his own soul, but he who is cruel troubles his own flesh.", reference: "Proverbs 11:17" },
  { text: "Wicked people earn deceitful wages, but one who sows righteousness reaps a sure reward.", reference: "Proverbs 11:18" },
  { text: "He who is truly righteous gets life. He who pursues evil gets death.", reference: "Proverbs 11:19" },
  { text: "Those who are perverse in heart are an abomination to Yahweh, but those whose ways are blameless are his delight.", reference: "Proverbs 11:20" },
  { text: "Most certainly, the evil man will not be unpunished, but the offspring of the righteous will be delivered.", reference: "Proverbs 11:21" },
  { text: "Like a gold ring in a pig’s snout, is a beautiful woman who lacks discretion.", reference: "Proverbs 11:22" },
  { text: "The desire of the righteous is only good. The expectation of the wicked is wrath.", reference: "Proverbs 11:23" },
  { text: "There is one who scatters, and increases yet more. There is one who withholds more than is appropriate, but gains poverty.", reference: "Proverbs 11:24" },
  { text: "The liberal soul shall be made fat. He who waters shall be watered also himself.", reference: "Proverbs 11:25" },
  { text: "People curse someone who withholds grain, but blessing will be on the head of him who sells it.", reference: "Proverbs 11:26" },
  { text: "He who diligently seeks good seeks favor, but he who searches after evil, it shall come to him.", reference: "Proverbs 11:27" },
  { text: "He who trusts in his riches will fall, but the righteous shall flourish as the green leaf.", reference: "Proverbs 11:28" },
  { text: "He who troubles his own house shall inherit the wind. The foolish shall be servant to the wise of heart.", reference: "Proverbs 11:29" },
  { text: "The fruit of the righteous is a tree of life. He who is wise wins souls.", reference: "Proverbs 11:30" },
  { text: "Behold, the righteous shall be repaid in the earth; how much more the wicked and the sinner!", reference: "Proverbs 11:31" },
  { text: "Whoever loves correction loves knowledge, but he who hates reproof is stupid.", reference: "Proverbs 12:1" },
  { text: "A good man shall obtain favor from Yahweh, but he will condemn a man of wicked plans.", reference: "Proverbs 12:2" },
  { text: "A man shall not be established by wickedness, but the root of the righteous shall not be moved.", reference: "Proverbs 12:3" },
  { text: "A worthy woman is the crown of her husband, but a disgraceful wife is as rottenness in his bones.", reference: "Proverbs 12:4" },
  { text: "The thoughts of the righteous are just, but the advice of the wicked is deceitful.", reference: "Proverbs 12:5" },
  { text: "The words of the wicked are about lying in wait for blood, but the speech of the upright rescues them.", reference: "Proverbs 12:6" },
  { text: "The wicked are overthrown, and are no more, but the house of the righteous shall stand.", reference: "Proverbs 12:7" },
  { text: "A man shall be commended according to his wisdom, but he who has a warped mind shall be despised.", reference: "Proverbs 12:8" },
  { text: "Better is he who is little know, and has a servant, than he who honors himself, and lacks bread.", reference: "Proverbs 12:9" },
  { text: "A righteous man respects the life of his animal, but the tender mercies of the wicked are cruel.", reference: "Proverbs 12:10" },
  { text: "He who tills his land shall have plenty of bread, but he who chases fantasies is void of understanding.", reference: "Proverbs 12:11" },
  { text: "The wicked desires the plunder of evil men, but the root of the righteous flourishes.", reference: "Proverbs 12:12" },
  { text: "An evil man is trapped by sinfulness of lips, but the righteous shall come out of trouble.", reference: "Proverbs 12:13" },
  { text: "A man shall be satisfied with good by the fruit of his mouth. The work of a man’s hands shall be rewarded to him.", reference: "Proverbs 12:14" },
  { text: "The way of a fool is right in his own eyes, but he who is wise listens to counsel.", reference: "Proverbs 12:15" },
  { text: "A fool shows his annoyance the same day, but one who overlooks an insult is prudent.", reference: "Proverbs 12:16" },
  { text: "He who is truthful testifies honestly, but a false witness lies.", reference: "Proverbs 12:17" },
  { text: "There is one who speaks rashly like the piercing of a sword, but the tongue of the wise heals.", reference: "Proverbs 12:18" },
  { text: "Truth’s lips will be established forever, but a lying tongue is only momentary.", reference: "Proverbs 12:19" },
  { text: "Deceit is in the heart of those who plot evil, but joy comes to the promoters of peace.", reference: "Proverbs 12:20" },
  { text: "No mischief shall happen to the righteous, but the wicked shall be filled with evil.", reference: "Proverbs 12:21" },
  { text: "Lying lips are an abomination to Yahweh, but those who do the truth are his delight.", reference: "Proverbs 12:22" },
  { text: "A prudent man keeps his knowledge, but the hearts of fools proclaim foolishness.", reference: "Proverbs 12:23" },
  { text: "The hands of the diligent ones shall rule, but laziness ends in slave labor.", reference: "Proverbs 12:24" },
  { text: "Anxiety in a man’s heart weighs it down, but a kind word makes it glad.", reference: "Proverbs 12:25" },
  { text: "A righteous person is cautious in friendship, but the way of the wicked leads them astray.", reference: "Proverbs 12:26" },
  { text: "The slothful man doesn’t roast his game, but the possessions of diligent men are prized.", reference: "Proverbs 12:27" },
  { text: "In the way of righteousness is life; in its path there is no death.", reference: "Proverbs 12:28" },
  { text: "A wise son listens to his father’s instruction, but a scoffer doesn’t listen to rebuke.", reference: "Proverbs 13:1" },
  { text: "By the fruit of his lips, a man enjoys good things; but the unfaithful crave violence.", reference: "Proverbs 13:2" },
  { text: "He who guards his mouth guards his soul. One who opens wide his lips comes to ruin.", reference: "Proverbs 13:3" },
  { text: "The soul of the sluggard desires, and has nothing, but the desire of the diligent shall be fully satisfied.", reference: "Proverbs 13:4" },
  { text: "A righteous man hates lies, but a wicked man brings shame and disgrace.", reference: "Proverbs 13:5" },
  { text: "Righteousness guards the way of integrity, but wickedness overthrows the sinner.", reference: "Proverbs 13:6" },
  { text: "There are some who pretend to be rich, yet have nothing. There are some who pretend to be poor, yet have great wealth.", reference: "Proverbs 13:7" },
  { text: "The ransom of a man’s life is his riches, but the poor hear no threats.", reference: "Proverbs 13:8" },
  { text: "The light of the righteous shines brightly, but the lamp of the wicked is snuffed out.", reference: "Proverbs 13:9" },
  { text: "Pride only breeds quarrels, but with ones who take advice is wisdom.", reference: "Proverbs 13:10" },
  { text: "Wealth gained dishonestly dwindles away, but he who gathers by hand makes it grow.", reference: "Proverbs 13:11" },
  { text: "Hope deferred makes the heart sick, but when longing is fulfilled, it is a tree of life.", reference: "Proverbs 13:12" },
  { text: "Whoever despises instruction will pay for it, but he who respects a command will be rewarded.", reference: "Proverbs 13:13" },
  { text: "The teaching of the wise is a spring of life, to turn from the snares of death.", reference: "Proverbs 13:14" },
  { text: "Good understanding wins favor; but the way of the unfaithful is hard.", reference: "Proverbs 13:15" },
  { text: "Every prudent man acts from knowledge, but a fool exposes folly.", reference: "Proverbs 13:16" },
  { text: "A wicked messenger falls into trouble, but a trustworthy envoy gains healing.", reference: "Proverbs 13:17" },
  { text: "Poverty and shame come to him who refuses discipline, but he who heeds correction shall be honored.", reference: "Proverbs 13:18" },
  { text: "Longing fulfilled is sweet to the soul, but fools detest turning from evil.", reference: "Proverbs 13:19" },
  { text: "One who walks with wise men grows wise, but a companion of fools suffers harm.", reference: "Proverbs 13:20" },
  { text: "Misfortune pursues sinners, but prosperity rewards the righteous.", reference: "Proverbs 13:21" },
  { text: "A good man leaves an inheritance to his children’s children, but the wealth of the sinner is stored for the righteous.", reference: "Proverbs 13:22" },
  { text: "An abundance of food is in poor people’s fields, but injustice sweeps it away.", reference: "Proverbs 13:23" },
  { text: "One who spares the rod hates his son, but one who loves him is careful to discipline him.", reference: "Proverbs 13:24" },
  { text: "The righteous one eats to the satisfying of his soul, but the belly of the wicked goes hungry.", reference: "Proverbs 13:25" },
  { text: "Every wise woman builds her house, but the foolish one tears it down with her own hands.", reference: "Proverbs 14:1" },
  { text: "He who walks in his uprightness fears Yahweh, but he who is perverse in his ways despises him.", reference: "Proverbs 14:2" },
  { text: "The fool’s talk brings a rod to his back, but the lips of the wise protect them.", reference: "Proverbs 14:3" },
  { text: "Where no oxen are, the crib is clean, but much increase is by the strength of the ox.", reference: "Proverbs 14:4" },
  { text: "A truthful witness will not lie, but a false witness pours out lies.", reference: "Proverbs 14:5" },
  { text: "A scoffer seeks wisdom, and doesn’t find it, but knowledge comes easily to a discerning person.", reference: "Proverbs 14:6" },
  { text: "Stay away from a foolish man, for you won’t find knowledge on his lips.", reference: "Proverbs 14:7" },
  { text: "The wisdom of the prudent is to think about his way, but the folly of fools is deceit.", reference: "Proverbs 14:8" },
  { text: "Fools mock at making atonement for sins, but among the upright there is good will.", reference: "Proverbs 14:9" },
  { text: "The heart knows its own bitterness and joy; he will not share these with a stranger.", reference: "Proverbs 14:10" },
  { text: "The house of the wicked will be overthrown, but the tent of the upright will flourish.", reference: "Proverbs 14:11" },
  { text: "There is a way which seems right to a man, but in the end it leads to death.", reference: "Proverbs 14:12" },
  { text: "Even in laughter the heart may be sorrowful, and mirth may end in heaviness.", reference: "Proverbs 14:13" },
  { text: "The unfaithful will be repaid for his own ways; likewise a good man will be rewarded for his ways.", reference: "Proverbs 14:14" },
  { text: "A simple man believes everything, but the prudent man carefully considers his ways.", reference: "Proverbs 14:15" },
  { text: "A wise man fears and shuns evil, but the fool is hot headed and reckless.", reference: "Proverbs 14:16" },
  { text: "He who is quick to become angry will commit folly, and a crafty man is hated.", reference: "Proverbs 14:17" },
  { text: "The simple inherit folly, but the prudent are crowned with knowledge.", reference: "Proverbs 14:18" },
  { text: "The evil bow down before the good, and the wicked at the gates of the righteous.", reference: "Proverbs 14:19" },
  { text: "The poor person is shunned even by his own neighbor, but the rich person has many friends.", reference: "Proverbs 14:20" },
  { text: "He who despises his neighbor sins, but blessed is he who has pity on the poor.", reference: "Proverbs 14:21" },
  { text: "Don’t they go astray who plot evil? But love and faithfulness belong to those who plan good.", reference: "Proverbs 14:22" },
  { text: "In all hard work there is profit, but the talk of the lips leads only to poverty.", reference: "Proverbs 14:23" },
  { text: "The crown of the wise is their riches, but the folly of fools crowns them with folly.", reference: "Proverbs 14:24" },
  { text: "A truthful witness saves souls, but a false witness is deceitful.", reference: "Proverbs 14:25" },
  { text: "In the fear of Yahweh is a secure fortress, and he will be a refuge for his children.", reference: "Proverbs 14:26" },
  { text: "The fear of Yahweh is a fountain of life, turning people from the snares of death.", reference: "Proverbs 14:27" },
  { text: "In the multitude of people is the king’s glory, but in the lack of people is the destruction of the prince.", reference: "Proverbs 14:28" },
  { text: "He who is slow to anger has great understanding, but he who has a quick temper displays folly.", reference: "Proverbs 14:29" },
  { text: "The life of the body is a heart at peace, but envy rots the bones.", reference: "Proverbs 14:30" },
  { text: "He who oppresses the poor shows contempt for his Maker, but he who is kind to the needy honors him.", reference: "Proverbs 14:31" },
  { text: "The wicked is brought down in his calamity, but in death, the righteous has a refuge.", reference: "Proverbs 14:32" },
  { text: "Wisdom rests in the heart of one who has understanding, and is even made known in the inward part of fools.", reference: "Proverbs 14:33" },
  { text: "Righteousness exalts a nation, but sin is a disgrace to any people.", reference: "Proverbs 14:34" },
  { text: "The king’s favor is toward a servant who deals wisely, but his wrath is toward one who causes shame.", reference: "Proverbs 14:35" },
  { text: "A gentle answer turns away wrath, but a harsh word stirs up anger.", reference: "Proverbs 15:1" },
  { text: "The tongue of the wise commends knowledge, but the mouth of fools gush out folly.", reference: "Proverbs 15:2" },
  { text: "Yahweh’s eyes are everywhere, keeping watch on the evil and the good.", reference: "Proverbs 15:3" },
  { text: "A gentle tongue is a tree of life, but deceit in it crushes the spirit.", reference: "Proverbs 15:4" },
  { text: "A fool despises his father’s correction, but he who heeds reproof shows prudence.", reference: "Proverbs 15:5" },
  { text: "In the house of the righteous is much treasure, but the income of the wicked brings trouble.", reference: "Proverbs 15:6" },
  { text: "The lips of the wise spread knowledge; not so with the heart of fools.", reference: "Proverbs 15:7" },
  { text: "The sacrifice made by the wicked is an abomination to Yahweh, but the prayer of the upright is his delight.", reference: "Proverbs 15:8" },
  { text: "The way of the wicked is an abomination to Yahweh, but he loves him who follows after righteousness.", reference: "Proverbs 15:9" },
  { text: "There is stern discipline for one who forsakes the way: whoever hates reproof shall die.", reference: "Proverbs 15:10" },
  { text: "Sheol and Abaddon are before Yahweh— how much more then the hearts of the children of men!", reference: "Proverbs 15:11" },
  { text: "A scoffer doesn’t love to be reproved; he will not go to the wise.", reference: "Proverbs 15:12" },
  { text: "A glad heart makes a cheerful face; but an aching heart breaks the spirit.", reference: "Proverbs 15:13" },
  { text: "The heart of one who has understanding seeks knowledge, but the mouths of fools feed on folly.", reference: "Proverbs 15:14" },
  { text: "All the days of the afflicted are wretched, but one who has a cheerful heart enjoys a continual feast.", reference: "Proverbs 15:15" },
  { text: "Better is little, with the fear of Yahweh, than great treasure with trouble.", reference: "Proverbs 15:16" },
  { text: "Better is a dinner of herbs, where love is, than a fattened calf with hatred.", reference: "Proverbs 15:17" },
  { text: "A wrathful man stirs up contention, but one who is slow to anger appeases strife.", reference: "Proverbs 15:18" },
  { text: "The way of the sluggard is like a thorn patch, but the path of the upright is a highway.", reference: "Proverbs 15:19" },
  { text: "A wise son makes a father glad, but a foolish man despises his mother.", reference: "Proverbs 15:20" },
  { text: "Folly is joy to one who is void of wisdom, but a man of understanding keeps his way straight.", reference: "Proverbs 15:21" },
  { text: "Where there is no counsel, plans fail; but in a multitude of counselors they are established.", reference: "Proverbs 15:22" },
  { text: "Joy comes to a man with the reply of his mouth. How good is a word at the right time!", reference: "Proverbs 15:23" },
  { text: "The path of life leads upward for the wise, to keep him from going downward to Sheol.", reference: "Proverbs 15:24" },
  { text: "Yahweh will uproot the house of the proud, but he will keep the widow’s borders intact.", reference: "Proverbs 15:25" },
  { text: "Yahweh detests the thoughts of the wicked, but the thoughts of the pure are pleasing.", reference: "Proverbs 15:26" },
  { text: "He who is greedy for gain troubles his own house, but he who hates bribes will live.", reference: "Proverbs 15:27" },
  { text: "The heart of the righteous weighs answers, but the mouth of the wicked gushes out evil.", reference: "Proverbs 15:28" },
  { text: "Yahweh is far from the wicked, but he hears the prayer of the righteous.", reference: "Proverbs 15:29" },
  { text: "The light of the eyes rejoices the heart. Good news gives health to the bones.", reference: "Proverbs 15:30" },
  { text: "The ear that listens to reproof lives, and will be at home among the wise.", reference: "Proverbs 15:31" },
  { text: "He who refuses correction despises his own soul, but he who listens to reproof gets understanding.", reference: "Proverbs 15:32" },
  { text: "The fear of Yahweh teaches wisdom. Before honor is humility.", reference: "Proverbs 15:33" },
  { text: "He also said to his disciples, “There was a certain rich man who had a manager. An accusation was made to him that this man was wasting his possessions.", reference: "Luke 16:1" },
  { text: "He called him, and said to him, ‘What is this that I hear about you? Give an accounting of your management, for you can no longer be manager.’", reference: "Luke 16:2" },
  { text: "“The manager said within himself, ‘What will I do, seeing that my lord is taking away the management position from me? I don’t have strength to dig. I am ashamed to beg.", reference: "Luke 16:3" },
  { text: "I know what I will do, so that when I am removed from management, they may receive me into their houses.’", reference: "Luke 16:4" },
  { text: "Calling each one of his lord’s debtors to him, he said to the first, ‘How much do you owe to my lord?’", reference: "Luke 16:5" },
  { text: "He said, ‘A hundred batos of oil.’ He said to him, ‘Take your bill, and sit down quickly and write fifty.’", reference: "Luke 16:6" },
  { text: "Then he said to another, ‘How much do you owe?’ He said, ‘A hundred cors of wheat.’ He said to him, ‘Take your bill, and write eighty.’", reference: "Luke 16:7" },
  { text: "“His lord commended the dishonest manager because he had done wisely, for the children of this world are, in their own generation, wiser than the children of the light.", reference: "Luke 16:8" },
  { text: "I tell you, make for yourselves friends by means of unrighteous mammon, so that when you fail, they may receive you into the eternal tents.", reference: "Luke 16:9" },
  { text: "He who is faithful in a very little is faithful also in much. He who is dishonest in a very little is also dishonest in much.", reference: "Luke 16:10" },
  { text: "If therefore you have not been faithful in the unrighteous mammon, who will commit to your trust the true riches?", reference: "Luke 16:11" },
  { text: "If you have not been faithful in that which is another’s, who will give you that which is your own?", reference: "Luke 16:12" },
  { text: "No servant can serve two masters, for either he will hate the one, and love the other; or else he will hold to one, and despise the other. You aren’t able to serve God and Mammon.”", reference: "Luke 16:13" },
  { text: "The Pharisees, who were lovers of money, also heard all these things, and they scoffed at him.", reference: "Luke 16:14" },
  { text: "He said to them, “You are those who justify yourselves in the sight of men, but God knows your hearts. For that which is exalted among men is an abomination in the sight of God.", reference: "Luke 16:15" },
  { text: "The law and the prophets were until John. From that time the Good News of God’s Kingdom is preached, and everyone is forcing his way into it.", reference: "Luke 16:16" },
  { text: "But it is easier for heaven and earth to pass away, than for one tiny stroke of a pen in the law to fall.", reference: "Luke 16:17" },
  { text: "Everyone who divorces his wife, and marries another, commits adultery. He who marries one who is divorced from a husband commits adultery.", reference: "Luke 16:18" },
  { text: "“Now there was a certain rich man, and he was clothed in purple and fine linen, living in luxury every day.", reference: "Luke 16:19" },
  { text: "A certain beggar, named Lazarus, was taken to his gate, full of sores,", reference: "Luke 16:20" },
  { text: "and desiring to be fed with the crumbs that fell from the rich man’s table. Yes, even the dogs came and licked his sores.", reference: "Luke 16:21" },
  { text: "The beggar died, and he was carried away by the angels to Abraham’s bosom. The rich man also died, and was buried.", reference: "Luke 16:22" },
  { text: "In Hades, he lifted up his eyes, being in torment, and saw Abraham far off, and Lazarus at his bosom.", reference: "Luke 16:23" },
  { text: "He cried and said, ‘Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, and cool my tongue! For I am in anguish in this flame.’", reference: "Luke 16:24" },
  { text: "“But Abraham said, ‘Son, remember that you, in your lifetime, received your good things, and Lazarus, in the same way, bad things. But here he is now comforted, and you are in anguish.", reference: "Luke 16:25" },
  { text: "Besides all this, between us and you there is a great gulf fixed, that those who want to pass from here to you are not able, and that no one may cross over from there to us.’", reference: "Luke 16:26" },
  { text: "“He said, ‘I ask you therefore, father, that you would send him to my father’s house;", reference: "Luke 16:27" },
  { text: "for I have five brothers, that he may testify to them, so they won’t also come into this place of torment.’", reference: "Luke 16:28" },
  { text: "“But Abraham said to him, ‘They have Moses and the prophets. Let them listen to them.’", reference: "Luke 16:29" },
  { text: "“He said, ‘No, father Abraham, but if one goes to them from the dead, they will repent.’", reference: "Luke 16:30" },
  { text: "“He said to him, ‘If they don’t listen to Moses and the prophets, neither will they be persuaded if one rises from the dead.’”", reference: "Luke 16:31" },
  { text: "He said to the disciples, “It is impossible that no occasions of stumbling should come, but woe to him through whom they come!", reference: "Luke 17:1" },
  { text: "It would be better for him if a millstone were hung around his neck, and he were thrown into the sea, rather than that he should cause one of these little ones to stumble.", reference: "Luke 17:2" },
  { text: "Be careful. If your brother sins against you, rebuke him. If he repents, forgive him.", reference: "Luke 17:3" },
  { text: "If he sins against you seven times in the day, and seven times returns, saying, ‘I repent,’ you shall forgive him.”", reference: "Luke 17:4" },
  { text: "The apostles said to the Lord, “Increase our faith.”", reference: "Luke 17:5" },
  { text: "The Lord said, “If you had faith like a grain of mustard seed, you would tell this sycamore tree, ‘Be uprooted, and be planted in the sea,’ and it would obey you.", reference: "Luke 17:6" },
  { text: "But who is there among you, having a servant plowing or keeping sheep, that will say, when he comes in from the field, ‘Come immediately and sit down at the table,’", reference: "Luke 17:7" },
  { text: "and will not rather tell him, ‘Prepare my supper, clothe yourself properly, and serve me, while I eat and drink. Afterward you shall eat and drink’?", reference: "Luke 17:8" },
  { text: "Does he thank that servant because he did the things that were commanded? I think not.", reference: "Luke 17:9" },
  { text: "Even so you also, when you have done all the things that are commanded you, say, ‘We are unworthy servants. We have done our duty.’”", reference: "Luke 17:10" },
  { text: "As he was on his way to Jerusalem, he was passing along the borders of Samaria and Galilee.", reference: "Luke 17:11" },
  { text: "As he entered into a certain village, ten men who were lepers met him, who stood at a distance.", reference: "Luke 17:12" },
  { text: "They lifted up their voices, saying, “Jesus, Master, have mercy on us!”", reference: "Luke 17:13" },
  { text: "When he saw them, he said to them, “Go and show yourselves to the priests.” As they went, they were cleansed.", reference: "Luke 17:14" },
  { text: "One of them, when he saw that he was healed, turned back, glorifying God with a loud voice.", reference: "Luke 17:15" },
  { text: "He fell on his face at Jesus’ feet, giving him thanks; and he was a Samaritan.", reference: "Luke 17:16" },
  { text: "Jesus answered, “Weren’t the ten cleansed? But where are the nine?", reference: "Luke 17:17" },
  { text: "Were there none found who returned to give glory to God, except this stranger?”", reference: "Luke 17:18" },
  { text: "Then he said to him, “Get up, and go your way. Your faith has healed you.”", reference: "Luke 17:19" },
  { text: "Being asked by the Pharisees when God’s Kingdom would come, he answered them, “God’s Kingdom doesn’t come with observation;", reference: "Luke 17:20" },
  { text: "neither will they say, ‘Look, here!’ or, ‘Look, there!’ for behold, God’s Kingdom is within you.”", reference: "Luke 17:21" },
  { text: "He said to the disciples, “The days will come, when you will desire to see one of the days of the Son of Man, and you will not see it.", reference: "Luke 17:22" },
  { text: "They will tell you, ‘Look, here!’ or ‘Look, there!’ Don’t go away, nor follow after them,", reference: "Luke 17:23" },
  { text: "for as the lightning, when it flashes out of the one part under the sky, shines to the other part under the sky; so will the Son of Man be in his day.", reference: "Luke 17:24" },
  { text: "But first, he must suffer many things and be rejected by this generation.", reference: "Luke 17:25" },
  { text: "As it was in the days of Noah, even so will it be also in the days of the Son of Man.", reference: "Luke 17:26" },
  { text: "They ate, they drank, they married, they were given in marriage, until the day that Noah entered into the ship, and the flood came, and destroyed them all.", reference: "Luke 17:27" },
  { text: "Likewise, even as it was in the days of Lot: they ate, they drank, they bought, they sold, they planted, they built;", reference: "Luke 17:28" },
  { text: "but in the day that Lot went out from Sodom, it rained fire and sulfur from the sky, and destroyed them all.", reference: "Luke 17:29" },
  { text: "It will be the same way in the day that the Son of Man is revealed.", reference: "Luke 17:30" },
  { text: "In that day, he who will be on the housetop, and his goods in the house, let him not go down to take them away. Let him who is in the field likewise not turn back.", reference: "Luke 17:31" },
  { text: "Whoever seeks to save his life loses it, but whoever loses his life preserves it.", reference: "Luke 17:33" },
  { text: "I tell you, in that night there will be two people in one bed. The one will be taken, and the other will be left.", reference: "Luke 17:34" },
  { text: "There will be two grinding grain together. One will be taken, and the other will be left.”", reference: "Luke 17:35" },
  { text: "They, answering, asked him, “Where, Lord?” He said to them, “Where the body is, there will the vultures also be gathered together.”", reference: "Luke 17:37" },
  { text: "He also spoke a parable to them that they must always pray, and not give up,", reference: "Luke 18:1" },
  { text: "saying, “There was a judge in a certain city who didn’t fear God, and didn’t respect man.", reference: "Luke 18:2" },
  { text: "A widow was in that city, and she often came to him, saying, ‘Defend me from my adversary!’", reference: "Luke 18:3" },
  { text: "He wouldn’t for a while, but afterward he said to himself, ‘Though I neither fear God, nor respect man,", reference: "Luke 18:4" },
  { text: "yet because this widow bothers me, I will defend her, or else she will wear me out by her continual coming.’”", reference: "Luke 18:5" },
  { text: "The Lord said, “Listen to what the unrighteous judge says.", reference: "Luke 18:6" },
  { text: "Won’t God avenge his chosen ones, who are crying out to him day and night, and yet he exercises patience with them?", reference: "Luke 18:7" },
  { text: "I tell you that he will avenge them quickly. Nevertheless, when the Son of Man comes, will he find faith on the earth?”", reference: "Luke 18:8" },
  { text: "He spoke also this parable to certain people who were convinced of their own righteousness, and who despised all others.", reference: "Luke 18:9" },
  { text: "“Two men went up into the temple to pray; one was a Pharisee, and the other was a tax collector.", reference: "Luke 18:10" },
  { text: "The Pharisee stood and prayed to himself like this: ‘God, I thank you, that I am not like the rest of men, extortionists, unrighteous, adulterers, or even like this tax collector.", reference: "Luke 18:11" },
  { text: "I fast twice a week. I give tithes of all that I get.’", reference: "Luke 18:12" },
  { text: "But the tax collector, standing far away, wouldn’t even lift up his eyes to heaven, but beat his breast, saying, ‘God, be merciful to me, a sinner!’", reference: "Luke 18:13" },
  { text: "I tell you, this man went down to his house justified rather than the other; for everyone who exalts himself will be humbled, but he who humbles himself will be exalted.”", reference: "Luke 18:14" },
  { text: "They were also bringing their babies to him, that he might touch them. But when the disciples saw it, they rebuked them.", reference: "Luke 18:15" },
  { text: "Jesus summoned them, saying, “Allow the little children to come to me, and don’t hinder them, for God’s Kingdom belongs to such as these.", reference: "Luke 18:16" },
  { text: "Most certainly, I tell you, whoever doesn’t receive God’s Kingdom like a little child, he will in no way enter into it.”", reference: "Luke 18:17" },
  { text: "A certain ruler asked him, saying, “Good Teacher, what shall I do to inherit eternal life?”", reference: "Luke 18:18" },
  { text: "Jesus asked him, “Why do you call me good? No one is good, except one—God.", reference: "Luke 18:19" },
  { text: "You know the commandments: ‘Don’t commit adultery,’ ‘Don’t murder,’ ‘Don’t steal,’ ‘Don’t give false testimony,’ ‘Honor your father and your mother.’”", reference: "Luke 18:20" },
  { text: "He said, “I have observed all these things from my youth up.”", reference: "Luke 18:21" },
  { text: "When Jesus heard these things, he said to him, “You still lack one thing. Sell all that you have, and distribute it to the poor. You will have treasure in heaven. Come, follow me.”", reference: "Luke 18:22" },
  { text: "But when he heard these things, he became very sad, for he was very rich.", reference: "Luke 18:23" },
  { text: "Jesus, seeing that he became very sad, said, “How hard it is for those who have riches to enter into God’s Kingdom!", reference: "Luke 18:24" },
  { text: "For it is easier for a camel to enter in through a needle’s eye, than for a rich man to enter into God’s Kingdom.”", reference: "Luke 18:25" },
  { text: "Those who heard it said, “Then who can be saved?”", reference: "Luke 18:26" },
  { text: "But he said, “The things which are impossible with men are possible with God.”", reference: "Luke 18:27" },
  { text: "Peter said, “Look, we have left everything, and followed you.”", reference: "Luke 18:28" },
  { text: "He said to them, “Most certainly I tell you, there is no one who has left house, or wife, or brothers, or parents, or children, for God’s Kingdom’s sake,", reference: "Luke 18:29" },
  { text: "who will not receive many times more in this time, and in the world to come, eternal life.”", reference: "Luke 18:30" },
  { text: "He took the twelve aside, and said to them, “Behold, we are going up to Jerusalem, and all the things that are written through the prophets concerning the Son of Man will be completed.", reference: "Luke 18:31" },
  { text: "For he will be delivered up to the Gentiles, will be mocked, treated shamefully, and spit on.", reference: "Luke 18:32" },
  { text: "They will scourge and kill him. On the third day, he will rise again.”", reference: "Luke 18:33" },
  { text: "They understood none of these things. This saying was hidden from them, and they didn’t understand the things that were said.", reference: "Luke 18:34" },
  { text: "As he came near Jericho, a certain blind man sat by the road, begging.", reference: "Luke 18:35" },
  { text: "Hearing a multitude going by, he asked what this meant.", reference: "Luke 18:36" },
  { text: "They told him that Jesus of Nazareth was passing by.", reference: "Luke 18:37" },
  { text: "He cried out, “Jesus, you son of David, have mercy on me!”", reference: "Luke 18:38" },
  { text: "Those who led the way rebuked him, that he should be quiet; but he cried out all the more, “You son of David, have mercy on me!”", reference: "Luke 18:39" },
  { text: "Standing still, Jesus commanded him to be brought to him. When he had come near, he asked him,", reference: "Luke 18:40" },
  { text: "“What do you want me to do?” He said, “Lord, that I may see again.”", reference: "Luke 18:41" },
  { text: "Jesus said to him, “Receive your sight. Your faith has healed you.”", reference: "Luke 18:42" },
  { text: "Immediately he received his sight, and followed him, glorifying God. All the people, when they saw it, praised God.", reference: "Luke 18:43" },
  { text: "There was a man named Zacchaeus. He was a chief tax collector, and he was rich.", reference: "Luke 19:2" },
  { text: "He was trying to see who Jesus was, and couldn’t because of the crowd, because he was short.", reference: "Luke 19:3" },
  { text: "He ran on ahead, and climbed up into a sycamore tree to see him, for he was going to pass that way.", reference: "Luke 19:4" },
  { text: "When Jesus came to the place, he looked up and saw him, and said to him, “Zacchaeus, hurry and come down, for today I must stay at your house.”", reference: "Luke 19:5" },
  { text: "He hurried, came down, and received him joyfully.", reference: "Luke 19:6" },
  { text: "When they saw it, they all murmured, saying, “He has gone in to lodge with a man who is a sinner.”", reference: "Luke 19:7" },
  { text: "Zacchaeus stood and said to the Lord, “Behold, Lord, half of my goods I give to the poor. If I have wrongfully exacted anything of anyone, I restore four times as much.”", reference: "Luke 19:8" },
  { text: "Jesus said to him, “Today, salvation has come to this house, because he also is a son of Abraham.", reference: "Luke 19:9" },
  { text: "For the Son of Man came to seek and to save that which was lost.”", reference: "Luke 19:10" },
  { text: "As they heard these things, he went on and told a parable, because he was near Jerusalem, and they supposed that God’s Kingdom would be revealed immediately.", reference: "Luke 19:11" },
  { text: "He said therefore, “A certain nobleman went into a far country to receive for himself a kingdom, and to return.", reference: "Luke 19:12" },
  { text: "He called ten servants of his, and gave them ten mina coins, and told them, ‘Conduct business until I come.’", reference: "Luke 19:13" },
  { text: "But his citizens hated him, and sent an envoy after him, saying, ‘We don’t want this man to reign over us.’", reference: "Luke 19:14" },
  { text: "The first came before him, saying, ‘Lord, your mina has made ten more minas.’", reference: "Luke 19:16" },
  { text: "“He said to him, ‘Well done, you good servant! Because you were found faithful with very little, you shall have authority over ten cities.’", reference: "Luke 19:17" },
  { text: "“The second came, saying, ‘Your mina, Lord, has made five minas.’", reference: "Luke 19:18" },
  { text: "“So he said to him, ‘And you are to be over five cities.’", reference: "Luke 19:19" },
  { text: "Another came, saying, ‘Lord, behold, your mina, which I kept laid away in a handkerchief,", reference: "Luke 19:20" },
  { text: "for I feared you, because you are an exacting man. You take up that which you didn’t lay down, and reap that which you didn’t sow.’", reference: "Luke 19:21" },
  { text: "“He said to him, ‘Out of your own mouth will I judge you, you wicked servant! You knew that I am an exacting man, taking up that which I didn’t lay down, and reaping that which I didn’t sow.", reference: "Luke 19:22" },
  { text: "Then why didn’t you deposit my money in the bank, and at my coming, I might have earned interest on it?’", reference: "Luke 19:23" },
  { text: "He said to those who stood by, ‘Take the mina away from him, and give it to him who has the ten minas.’", reference: "Luke 19:24" },
  { text: "‘For I tell you that to everyone who has, will more be given; but from him who doesn’t have, even that which he has will be taken away from him.", reference: "Luke 19:26" },
  { text: "But bring those enemies of mine who didn’t want me to reign over them here, and kill them before me.’”", reference: "Luke 19:27" },
  { text: "Having said these things, he went on ahead, going up to Jerusalem.", reference: "Luke 19:28" },
  { text: "When he came near to Bethsphage and Bethany, at the mountain that is called Olivet, he sent two of his disciples,", reference: "Luke 19:29" },
  { text: "saying, “Go your way into the village on the other side, in which, as you enter, you will find a colt tied, which no man had ever sat upon. Untie it, and bring it.", reference: "Luke 19:30" },
  { text: "If anyone asks you, ‘Why are you untying it?’ say to him: ‘The Lord needs it.’”", reference: "Luke 19:31" },
  { text: "Those who were sent went away, and found things just as he had told them.", reference: "Luke 19:32" },
  { text: "As they were untying the colt, its owners said to them, “Why are you untying the colt?”", reference: "Luke 19:33" },
  { text: "They brought it to Jesus. They threw their cloaks on the colt, and set Jesus on them.", reference: "Luke 19:35" },
  { text: "As he went, they spread their cloaks on the road.", reference: "Luke 19:36" },
  { text: "As he was now getting near, at the descent of the Mount of Olives, the whole multitude of the disciples began to rejoice and praise God with a loud voice for all the mighty works which they had seen,", reference: "Luke 19:37" },
  { text: "saying, “Blessed is the King who comes in the name of the Lord! Peace in heaven, and glory in the highest!”", reference: "Luke 19:38" },
  { text: "Some of the Pharisees from the multitude said to him, “Teacher, rebuke your disciples!”", reference: "Luke 19:39" },
  { text: "He answered them, “I tell you that if these were silent, the stones would cry out.”", reference: "Luke 19:40" },
  { text: "When he came near, he saw the city and wept over it,", reference: "Luke 19:41" },
  { text: "saying, “If you, even you, had known today the things which belong to your peace! But now, they are hidden from your eyes.", reference: "Luke 19:42" },
  { text: "For the days will come on you, when your enemies will throw up a barricade against you, surround you, hem you in on every side,", reference: "Luke 19:43" },
  { text: "and will dash you and your children within you to the ground. They will not leave in you one stone on another, because you didn’t know the time of your visitation.”", reference: "Luke 19:44" },
  { text: "He entered into the temple, and began to drive out those who bought and sold in it,", reference: "Luke 19:45" },
  { text: "saying to them, “It is written, ‘My house is a house of prayer,’ but you have made it a ‘den of robbers’!”", reference: "Luke 19:46" },
  { text: "He was teaching daily in the temple, but the chief priests and the scribes and the leading men among the people sought to destroy him.", reference: "Luke 19:47" },
  { text: "They couldn’t find what they might do, for all the people hung on to every word that he said.", reference: "Luke 19:48" },
  { text: "On one of those days, as he was teaching the people in the temple and preaching the Good News, the priests and scribes came to him with the elders.", reference: "Luke 20:1" },
  { text: "They asked him, “Tell us: by what authority do you do these things? Or who is giving you this authority?”", reference: "Luke 20:2" },
  { text: "He answered them, “I also will ask you one question. Tell me:", reference: "Luke 20:3" },
  { text: "the baptism of John, was it from heaven, or from men?”", reference: "Luke 20:4" },
  { text: "They reasoned with themselves, saying, “If we say, ‘From heaven,’ he will say, ‘Why didn’t you believe him?’", reference: "Luke 20:5" },
  { text: "But if we say, ‘From men,’ all the people will stone us, for they are persuaded that John was a prophet.”", reference: "Luke 20:6" },
  { text: "They answered that they didn’t know where it was from.", reference: "Luke 20:7" },
  { text: "Jesus said to them, “Neither will I tell you by what authority I do these things.”", reference: "Luke 20:8" },
  { text: "He began to tell the people this parable. “A man planted a vineyard, and rented it out to some farmers, and went into another country for a long time.", reference: "Luke 20:9" },
  { text: "At the proper season, he sent a servant to the farmers to collect his share of the fruit of the vineyard. But the farmers beat him, and sent him away empty.", reference: "Luke 20:10" },
  { text: "He sent yet another servant, and they also beat him, and treated him shamefully, and sent him away empty.", reference: "Luke 20:11" },
  { text: "He sent yet a third, and they also wounded him, and threw him out.", reference: "Luke 20:12" },
  { text: "The lord of the vineyard said, ‘What shall I do? I will send my beloved son. It may be that seeing him, they will respect him.’", reference: "Luke 20:13" },
  { text: "“But when the farmers saw him, they reasoned among themselves, saying, ‘This is the heir. Come, let’s kill him, that the inheritance may be ours.’", reference: "Luke 20:14" },
  { text: "They threw him out of the vineyard, and killed him. What therefore will the lord of the vineyard do to them?", reference: "Luke 20:15" },
  { text: "He will come and destroy these farmers, and will give the vineyard to others.” When they heard it, they said, “May it never be!”", reference: "Luke 20:16" },
  { text: "But he looked at them, and said, “Then what is this that is written, ‘The stone which the builders rejected, the same was made the chief cornerstone?’", reference: "Luke 20:17" },
  { text: "Everyone who falls on that stone will be broken to pieces, but it will crush whomever it falls on to dust.”", reference: "Luke 20:18" },
  { text: "The chief priests and the scribes sought to lay hands on him that very hour, but they feared the people—for they knew he had spoken this parable against them.", reference: "Luke 20:19" },
  { text: "They watched him, and sent out spies, who pretended to be righteous, that they might trap him in something he said, so as to deliver him up to the power and authority of the governor.", reference: "Luke 20:20" },
  { text: "They asked him, “Teacher, we know that you say and teach what is right, and aren’t partial to anyone, but truly teach the way of God.", reference: "Luke 20:21" },
  { text: "Is it lawful for us to pay taxes to Caesar, or not?”", reference: "Luke 20:22" },
  { text: "But he perceived their craftiness, and said to them, “Why do you test me?", reference: "Luke 20:23" },
  { text: "Show me a denarius. Whose image and inscription are on it?” They answered, “Caesar’s.”", reference: "Luke 20:24" },
  { text: "He said to them, “Then give to Caesar the things that are Caesar’s, and to God the things that are God’s.”", reference: "Luke 20:25" },
  { text: "They weren’t able to trap him in his words before the people. They marveled at his answer, and were silent.", reference: "Luke 20:26" },
  { text: "Some of the Sadducees came to him, those who deny that there is a resurrection.", reference: "Luke 20:27" },
  { text: "They asked him, “Teacher, Moses wrote to us that if a man’s brother dies having a wife, and he is childless, his brother should take the wife, and raise up children for his brother.", reference: "Luke 20:28" },
  { text: "There were therefore seven brothers. The first took a wife, and died childless.", reference: "Luke 20:29" },
  { text: "The second took her as wife, and he died childless.", reference: "Luke 20:30" },
  { text: "The third took her, and likewise the seven all left no children, and died.", reference: "Luke 20:31" },
  { text: "Therefore in the resurrection whose wife of them will she be? For the seven had her as a wife.”", reference: "Luke 20:33" },
  { text: "Jesus said to them, “The children of this age marry, and are given in marriage.", reference: "Luke 20:34" },
  { text: "But those who are considered worthy to attain to that age and the resurrection from the dead, neither marry, nor are given in marriage.", reference: "Luke 20:35" },
  { text: "For they can’t die any more, for they are like the angels, and are children of God, being children of the resurrection.", reference: "Luke 20:36" },
  { text: "But that the dead are raised, even Moses showed at the bush, when he called the Lord ‘The God of Abraham, the God of Isaac, and the God of Jacob.’", reference: "Luke 20:37" },
  { text: "Now he is not the God of the dead, but of the living, for all are alive to him.”", reference: "Luke 20:38" },
  { text: "Some of the scribes answered, “Teacher, you speak well.”", reference: "Luke 20:39" },
  { text: "They didn’t dare to ask him any more questions.", reference: "Luke 20:40" },
  { text: "He said to them, “Why do they say that the Christ is David’s son?", reference: "Luke 20:41" },
  { text: "David himself says in the book of Psalms, ‘The Lord said to my Lord, “Sit at my right hand,", reference: "Luke 20:42" },
  { text: "until I make your enemies the footstool of your feet.”’", reference: "Luke 20:43" },
  { text: "“David therefore calls him Lord, so how is he his son?”", reference: "Luke 20:44" },
  { text: "In the hearing of all the people, he said to his disciples,", reference: "Luke 20:45" },
  { text: "“Beware of those scribes who like to walk in long robes, and love greetings in the marketplaces, the best seats in the synagogues, and the best places at feasts;", reference: "Luke 20:46" },
  { text: "who devour widows’ houses, and for a pretense make long prayers: these will receive greater condemnation.”", reference: "Luke 20:47" },
  { text: "He looked up, and saw the rich people who were putting their gifts into the treasury.", reference: "Luke 21:1" },
  { text: "He saw a certain poor widow casting in two small brass coins.", reference: "Luke 21:2" },
  { text: "He said, “Truly I tell you, this poor widow put in more than all of them,", reference: "Luke 21:3" },
  { text: "for all these put in gifts for God from their abundance, but she, out of her poverty, put in all that she had to live on.”", reference: "Luke 21:4" },
  { text: "As some were talking about the temple and how it was decorated with beautiful stones and gifts, he said,", reference: "Luke 21:5" },
  { text: "“As for these things which you see, the days will come, in which there will not be left here one stone on another that will not be thrown down.”", reference: "Luke 21:6" },
  { text: "They asked him, “Teacher, so when will these things be? What is the sign that these things are about to happen?”", reference: "Luke 21:7" },
  { text: "He said, “Watch out that you don’t get led astray, for many will come in my name, saying, ‘I am he,’ and, ‘The time is at hand.’ Therefore don’t follow them.", reference: "Luke 21:8" },
  { text: "When you hear of wars and disturbances, don’t be terrified, for these things must happen first, but the end won’t come immediately.”", reference: "Luke 21:9" },
  { text: "Then he said to them, “Nation will rise against nation, and kingdom against kingdom.", reference: "Luke 21:10" },
  { text: "There will be great earthquakes, famines, and plagues in various places. There will be terrors and great signs from heaven.", reference: "Luke 21:11" },
  { text: "But before all these things, they will lay their hands on you and will persecute you, delivering you up to synagogues and prisons, bringing you before kings and governors for my name’s sake.", reference: "Luke 21:12" },
  { text: "Settle it therefore in your hearts not to meditate beforehand how to answer,", reference: "Luke 21:14" },
  { text: "for I will give you a mouth and wisdom which all your adversaries will not be able to withstand or to contradict.", reference: "Luke 21:15" },
  { text: "You will be handed over even by parents, brothers, relatives, and friends. They will cause some of you to be put to death.", reference: "Luke 21:16" },
  { text: "You will be hated by all men for my name’s sake.", reference: "Luke 21:17" },
  { text: "“But when you see Jerusalem surrounded by armies, then know that its desolation is at hand.", reference: "Luke 21:20" },
  { text: "Then let those who are in Judea flee to the mountains. Let those who are in the middle of her depart. Let those who are in the country not enter therein.", reference: "Luke 21:21" },
  { text: "For these are days of vengeance, that all things which are written may be fulfilled.", reference: "Luke 21:22" },
  { text: "Woe to those who are pregnant and to those who nurse infants in those days! For there will be great distress in the land, and wrath to this people.", reference: "Luke 21:23" },
  { text: "They will fall by the edge of the sword, and will be led captive into all the nations. Jerusalem will be trampled down by the Gentiles, until the times of the Gentiles are fulfilled.", reference: "Luke 21:24" },
  { text: "There will be signs in the sun, moon, and stars; and on the earth anxiety of nations, in perplexity for the roaring of the sea and the waves;", reference: "Luke 21:25" },
  { text: "men fainting for fear, and for expectation of the things which are coming on the world: for the powers of the heavens will be shaken.", reference: "Luke 21:26" },
  { text: "Then they will see the Son of Man coming in a cloud with power and great glory.", reference: "Luke 21:27" },
  { text: "But when these things begin to happen, look up, and lift up your heads, because your redemption is near.”", reference: "Luke 21:28" },
  { text: "He told them a parable. “See the fig tree, and all the trees.", reference: "Luke 21:29" },
  { text: "When they are already budding, you see it and know by your own selves that the summer is already near.", reference: "Luke 21:30" },
  { text: "Even so you also, when you see these things happening, know that God’s Kingdom is near.", reference: "Luke 21:31" },
  { text: "Most certainly I tell you, this generation will not pass away until all things are accomplished.", reference: "Luke 21:32" },
  { text: "Heaven and earth will pass away, but my words will by no means pass away.", reference: "Luke 21:33" },
  { text: "“So be careful, or your hearts will be loaded down with carousing, drunkenness, and cares of this life, and that day will come on you suddenly.", reference: "Luke 21:34" },
  { text: "For it will come like a snare on all those who dwell on the surface of all the earth.", reference: "Luke 21:35" },
  { text: "Therefore be watchful all the time, praying that you may be counted worthy to escape all these things that will happen, and to stand before the Son of Man.”", reference: "Luke 21:36" },
  { text: "Every day Jesus was teaching in the temple, and every night he would go out and spend the night on the mountain that is called Olivet.", reference: "Luke 21:37" },
  { text: "All the people came early in the morning to him in the temple to hear him.", reference: "Luke 21:38" },
  { text: "Now the feast of unleavened bread, which is called the Passover, was approaching.", reference: "Luke 22:1" },
  { text: "The chief priests and the scribes sought how they might put him to death, for they feared the people.", reference: "Luke 22:2" },
  { text: "Satan entered into Judas, who was also called Iscariot, who was counted with the twelve.", reference: "Luke 22:3" },
  { text: "He went away, and talked with the chief priests and captains about how he might deliver him to them.", reference: "Luke 22:4" },
  { text: "They were glad, and agreed to give him money.", reference: "Luke 22:5" },
  { text: "He consented, and sought an opportunity to deliver him to them in the absence of the multitude.", reference: "Luke 22:6" },
  { text: "The day of unleavened bread came, on which the Passover must be sacrificed.", reference: "Luke 22:7" },
  { text: "Jesus sent Peter and John, saying, “Go and prepare the Passover for us, that we may eat.”", reference: "Luke 22:8" },
  { text: "They said to him, “Where do you want us to prepare?”", reference: "Luke 22:9" },
  { text: "He said to them, “Behold, when you have entered into the city, a man carrying a pitcher of water will meet you. Follow him into the house which he enters.", reference: "Luke 22:10" },
  { text: "Tell the master of the house, ‘The Teacher says to you, “Where is the guest room, where I may eat the Passover with my disciples?”’", reference: "Luke 22:11" },
  { text: "He will show you a large, furnished upper room. Make preparations there.”", reference: "Luke 22:12" },
  { text: "They went, found things as Jesus had told them, and they prepared the Passover.", reference: "Luke 22:13" },
  { text: "When the hour had come, he sat down with the twelve apostles.", reference: "Luke 22:14" },
  { text: "He said to them, “I have earnestly desired to eat this Passover with you before I suffer,", reference: "Luke 22:15" },
  { text: "for I tell you, I will no longer by any means eat of it until it is fulfilled in God’s Kingdom.”", reference: "Luke 22:16" },
  { text: "He received a cup, and when he had given thanks, he said, “Take this, and share it among yourselves,", reference: "Luke 22:17" },
  { text: "for I tell you, I will not drink at all again from the fruit of the vine, until God’s Kingdom comes.”", reference: "Luke 22:18" },
  { text: "He took bread, and when he had given thanks, he broke, and gave it to them, saying, “This is my body which is given for you. Do this in memory of me.”", reference: "Luke 22:19" },
  { text: "Likewise, he took the cup after supper, saying, “This cup is the new covenant in my blood, which is poured out for you.", reference: "Luke 22:20" },
  { text: "But behold, the hand of him who betrays me is with me on the table.", reference: "Luke 22:21" },
  { text: "The Son of Man indeed goes, as it has been determined, but woe to that man through whom he is betrayed!”", reference: "Luke 22:22" },
  { text: "They began to question among themselves, which of them it was who would do this thing.", reference: "Luke 22:23" },
  { text: "There arose also a contention among them, which of them was considered to be greatest.", reference: "Luke 22:24" },
  { text: "He said to them, “The kings of the nations lord it over them, and those who have authority over them are called ‘benefactors.’", reference: "Luke 22:25" },
  { text: "But not so with you. But one who is the greater among you, let him become as the younger, and one who is governing, as one who serves.", reference: "Luke 22:26" },
  { text: "For who is greater, one who sits at the table, or one who serves? Isn’t it he who sits at the table? But I am among you as one who serves.", reference: "Luke 22:27" },
  { text: "But you are those who have continued with me in my trials.", reference: "Luke 22:28" },
  { text: "I confer on you a kingdom, even as my Father conferred on me,", reference: "Luke 22:29" },
  { text: "that you may eat and drink at my table in my Kingdom. You will sit on thrones, judging the twelve tribes of Israel.”", reference: "Luke 22:30" },
  { text: "The Lord said, “Simon, Simon, behold, Satan asked to have all of you, that he might sift you as wheat,", reference: "Luke 22:31" },
  { text: "but I prayed for you, that your faith wouldn’t fail. You, when once you have turned again, establish your brothers.”", reference: "Luke 22:32" },
  { text: "He said to him, “Lord, I am ready to go with you both to prison and to death!”", reference: "Luke 22:33" },
  { text: "He said, “I tell you, Peter, the rooster will by no means crow today until you deny that you know me three times.”", reference: "Luke 22:34" },
  { text: "He said to them, “When I sent you out without purse, and wallet, and shoes, did you lack anything?” They said, “Nothing.”", reference: "Luke 22:35" },
  { text: "Then he said to them, “But now, whoever has a purse, let him take it, and likewise a wallet. Whoever has none, let him sell his cloak, and buy a sword.", reference: "Luke 22:36" },
  { text: "For I tell you that this which is written must still be fulfilled in me: ‘He was counted with transgressors.’ For that which concerns me has an end.”", reference: "Luke 22:37" },
  { text: "They said, “Lord, behold, here are two swords.” He said to them, “That is enough.”", reference: "Luke 22:38" },
  { text: "He came out, and went, as his custom was, to the Mount of Olives. His disciples also followed him.", reference: "Luke 22:39" },
  { text: "When he was at the place, he said to them, “Pray that you don’t enter into temptation.”", reference: "Luke 22:40" },
  { text: "He was withdrawn from them about a stone’s throw, and he knelt down and prayed,", reference: "Luke 22:41" },
  { text: "saying, “Father, if you are willing, remove this cup from me. Nevertheless, not my will, but yours, be done.”", reference: "Luke 22:42" },
  { text: "An angel from heaven appeared to him, strengthening him.", reference: "Luke 22:43" },
  { text: "Being in agony he prayed more earnestly. His sweat became like great drops of blood falling down on the ground.", reference: "Luke 22:44" },
  { text: "When he rose up from his prayer, he came to the disciples, and found them sleeping because of grief,", reference: "Luke 22:45" },
  { text: "and said to them, “Why do you sleep? Rise and pray that you may not enter into temptation.”", reference: "Luke 22:46" },
  { text: "While he was still speaking, behold, a multitude, and he who was called Judas, one of the twelve, was leading them. He came near to Jesus to kiss him.", reference: "Luke 22:47" },
  { text: "But Jesus said to him, “Judas, do you betray the Son of Man with a kiss?”", reference: "Luke 22:48" },
  { text: "When those who were around him saw what was about to happen, they said to him, “Lord, shall we strike with the sword?”", reference: "Luke 22:49" },
  { text: "A certain one of them struck the servant of the high priest, and cut off his right ear.", reference: "Luke 22:50" },
  { text: "But Jesus answered, “Let me at least do this”—and he touched his ear, and healed him.", reference: "Luke 22:51" },
  { text: "Jesus said to the chief priests, captains of the temple, and elders, who had come against him, “Have you come out as against a robber, with swords and clubs?", reference: "Luke 22:52" },
  { text: "When I was with you in the temple daily, you didn’t stretch out your hands against me. But this is your hour, and the power of darkness.”", reference: "Luke 22:53" },
  { text: "They seized him, and led him away, and brought him into the high priest’s house. But Peter followed from a distance.", reference: "Luke 22:54" },
  { text: "When they had kindled a fire in the middle of the courtyard, and had sat down together, Peter sat among them.", reference: "Luke 22:55" },
  { text: "A certain servant girl saw him as he sat in the light, and looking intently at him, said, “This man also was with him.”", reference: "Luke 22:56" },
  { text: "He denied Jesus, saying, “Woman, I don’t know him.”", reference: "Luke 22:57" },
  { text: "After a little while someone else saw him, and said, “You also are one of them!” But Peter answered, “Man, I am not!”", reference: "Luke 22:58" },
  { text: "After about one hour passed, another confidently affirmed, saying, “Truly this man also was with him, for he is a Galilean!”", reference: "Luke 22:59" },
  { text: "But Peter said, “Man, I don’t know what you are talking about!” Immediately, while he was still speaking, a rooster crowed.", reference: "Luke 22:60" },
  { text: "The Lord turned, and looked at Peter. Then Peter remembered the Lord’s word, how he said to him, “Before the rooster crows you will deny me three times.”", reference: "Luke 22:61" },
  { text: "The men who held Jesus mocked him and beat him.", reference: "Luke 22:63" },
  { text: "Having blindfolded him, they struck him on the face and asked him, “Prophesy! Who is the one who struck you?”", reference: "Luke 22:64" },
  { text: "They spoke many other things against him, insulting him.", reference: "Luke 22:65" },
  { text: "As soon as it was day, the assembly of the elders of the people were gathered together, both chief priests and scribes, and they led him away into their council, saying,", reference: "Luke 22:66" },
  { text: "“If you are the Christ, tell us.” But he said to them, “If I tell you, you won’t believe,", reference: "Luke 22:67" },
  { text: "and if I ask, you will in no way answer me or let me go.", reference: "Luke 22:68" },
  { text: "From now on, the Son of Man will be seated at the right hand of the power of God.”", reference: "Luke 22:69" },
  { text: "They all said, “Are you then the Son of God?” He said to them, “You say it, because I am.”", reference: "Luke 22:70" },
  { text: "They said, “Why do we need any more witness? For we ourselves have heard from his own mouth!”", reference: "Luke 22:71" },
  { text: "The whole company of them rose up and brought him before Pilate.", reference: "Luke 23:1" },
  { text: "They began to accuse him, saying, “We found this man perverting the nation, forbidding paying taxes to Caesar, and saying that he himself is Christ, a king.”", reference: "Luke 23:2" },
  { text: "Pilate asked him, “Are you the King of the Jews?” He answered him, “So you say.”", reference: "Luke 23:3" },
  { text: "Pilate said to the chief priests and the multitudes, “I find no basis for a charge against this man.”", reference: "Luke 23:4" },
  { text: "But they insisted, saying, “He stirs up the people, teaching throughout all Judea, beginning from Galilee even to this place.”", reference: "Luke 23:5" },
  { text: "But when Pilate heard Galilee mentioned, he asked if the man was a Galilean.", reference: "Luke 23:6" },
  { text: "When he found out that he was in Herod’s jurisdiction, he sent him to Herod, who was also in Jerusalem during those days.", reference: "Luke 23:7" },
  { text: "Now when Herod saw Jesus, he was exceedingly glad, for he had wanted to see him for a long time, because he had heard many things about him. He hoped to see some miracle done by him.", reference: "Luke 23:8" },
  { text: "He questioned him with many words, but he gave no answers.", reference: "Luke 23:9" },
  { text: "The chief priests and the scribes stood, vehemently accusing him.", reference: "Luke 23:10" },
  { text: "Herod with his soldiers humiliated him and mocked him. Dressing him in luxurious clothing, they sent him back to Pilate.", reference: "Luke 23:11" },
  { text: "Herod and Pilate became friends with each other that very day, for before that they were enemies with each other.", reference: "Luke 23:12" },
  { text: "Pilate called together the chief priests, the rulers, and the people,", reference: "Luke 23:13" },
  { text: "Neither has Herod, for I sent you to him, and see, nothing worthy of death has been done by him.", reference: "Luke 23:15" },
  { text: "I will therefore chastise him and release him.”", reference: "Luke 23:16" },
  { text: "Now he had to release one prisoner to them at the feast.", reference: "Luke 23:17" },
  { text: "But they all cried out together, saying, “Away with this man! Release to us Barabbas!”—", reference: "Luke 23:18" },
  { text: "one who was thrown into prison for a certain revolt in the city, and for murder.", reference: "Luke 23:19" },
  { text: "Then Pilate spoke to them again, wanting to release Jesus,", reference: "Luke 23:20" },
  { text: "but they shouted, saying, “Crucify! Crucify him!”", reference: "Luke 23:21" },
  { text: "He said to them the third time, “Why? What evil has this man done? I have found no capital crime in him. I will therefore chastise him and release him.”", reference: "Luke 23:22" },
  { text: "But they were urgent with loud voices, asking that he might be crucified. Their voices and the voices of the chief priests prevailed.", reference: "Luke 23:23" },
  { text: "Pilate decreed that what they asked for should be done.", reference: "Luke 23:24" },
  { text: "He released him who had been thrown into prison for insurrection and murder, for whom they asked, but he delivered Jesus up to their will.", reference: "Luke 23:25" },
  { text: "When they led him away, they grabbed one Simon of Cyrene, coming from the country, and laid on him the cross, to carry it after Jesus.", reference: "Luke 23:26" },
  { text: "A great multitude of the people followed him, including women who also mourned and lamented him.", reference: "Luke 23:27" },
  { text: "But Jesus, turning to them, said, “Daughters of Jerusalem, don’t weep for me, but weep for yourselves and for your children.", reference: "Luke 23:28" },
  { text: "For behold, the days are coming in which they will say, ‘Blessed are the barren, the wombs that never bore, and the breasts that never nursed.’", reference: "Luke 23:29" },
  { text: "Then they will begin to tell the mountains, ‘Fall on us!’ and tell the hills, ‘Cover us.’", reference: "Luke 23:30" },
  { text: "For if they do these things in the green tree, what will be done in the dry?”", reference: "Luke 23:31" },
  { text: "There were also others, two criminals, led with him to be put to death.", reference: "Luke 23:32" },
  { text: "When they came to the place that is called The Skull, they crucified him there with the criminals, one on the right and the other on the left.", reference: "Luke 23:33" },
  { text: "Jesus said, “Father, forgive them, for they don’t know what they are doing.” Dividing his garments among them, they cast lots.", reference: "Luke 23:34" },
  { text: "The people stood watching. The rulers with them also scoffed at him, saying, “He saved others. Let him save himself, if this is the Christ of God, his chosen one!”", reference: "Luke 23:35" },
  { text: "The soldiers also mocked him, coming to him and offering him vinegar,", reference: "Luke 23:36" },
  { text: "and saying, “If you are the King of the Jews, save yourself!”", reference: "Luke 23:37" },
  { text: "An inscription was also written over him in letters of Greek, Latin, and Hebrew: “THIS IS THE KING OF THE JEWS.”", reference: "Luke 23:38" },
  { text: "One of the criminals who was hanged insulted him, saying, “If you are the Christ, save yourself and us!”", reference: "Luke 23:39" },
  { text: "But the other answered, and rebuking him said, “Don’t you even fear God, seeing you are under the same condemnation?", reference: "Luke 23:40" },
  { text: "And we indeed justly, for we receive the due reward for our deeds, but this man has done nothing wrong.”", reference: "Luke 23:41" },
  { text: "He said to Jesus, “Lord, remember me when you come into your Kingdom.”", reference: "Luke 23:42" },
  { text: "Jesus said to him, “Assuredly I tell you, today you will be with me in Paradise.”", reference: "Luke 23:43" },
  { text: "It was now about the sixth hour, and darkness came over the whole land until the ninth hour.", reference: "Luke 23:44" },
  { text: "The sun was darkened, and the veil of the temple was torn in two.", reference: "Luke 23:45" },
  { text: "Jesus, crying with a loud voice, said, “Father, into your hands I commit my spirit!” Having said this, he breathed his last.", reference: "Luke 23:46" },
  { text: "When the centurion saw what was done, he glorified God, saying, “Certainly this was a righteous man.”", reference: "Luke 23:47" },
  { text: "All the multitudes that came together to see this, when they saw the things that were done, returned home beating their breasts.", reference: "Luke 23:48" },
  { text: "All his acquaintances, and the women who followed with him from Galilee, stood at a distance, watching these things.", reference: "Luke 23:49" },
  { text: "Behold, a man named Joseph, who was a member of the council, a good and righteous man", reference: "Luke 23:50" },
  { text: "(he had not consented to their counsel and deed), from Arimathaea, a city of the Jews, who was also waiting for God’s Kingdom:", reference: "Luke 23:51" },
  { text: "this man went to Pilate, and asked for Jesus’ body.", reference: "Luke 23:52" },
  { text: "He took it down, and wrapped it in a linen cloth, and laid him in a tomb that was cut in stone, where no one had ever been laid.", reference: "Luke 23:53" },
  { text: "It was the day of the Preparation, and the Sabbath was drawing near.", reference: "Luke 23:54" },
  { text: "The women, who had come with him out of Galilee, followed after, and saw the tomb, and how his body was laid.", reference: "Luke 23:55" },
  { text: "They returned, and prepared spices and ointments. On the Sabbath they rested according to the commandment.", reference: "Luke 23:56" },
  { text: "But on the first day of the week, at early dawn, they and some others came to the tomb, bringing the spices which they had prepared.", reference: "Luke 24:1" },
  { text: "They found the stone rolled away from the tomb.", reference: "Luke 24:2" },
  { text: "They entered in, and didn’t find the Lord Jesus’ body.", reference: "Luke 24:3" },
  { text: "While they were greatly perplexed about this, behold, two men stood by them in dazzling clothing.", reference: "Luke 24:4" },
  { text: "Becoming terrified, they bowed their faces down to the earth. They said to them, “Why do you seek the living among the dead?", reference: "Luke 24:5" },
  { text: "He isn’t here, but is risen. Remember what he told you when he was still in Galilee,", reference: "Luke 24:6" },
  { text: "saying that the Son of Man must be delivered up into the hands of sinful men, and be crucified, and the third day rise again?”", reference: "Luke 24:7" },
  { text: "returned from the tomb, and told all these things to the eleven, and to all the rest.", reference: "Luke 24:9" },
  { text: "Now they were Mary Magdalene, Joanna, and Mary the mother of James. The other women with them told these things to the apostles.", reference: "Luke 24:10" },
  { text: "These words seemed to them to be nonsense, and they didn’t believe them.", reference: "Luke 24:11" },
  { text: "But Peter got up and ran to the tomb. Stooping and looking in, he saw the strips of linen lying by themselves, and he departed to his home, wondering what had happened.", reference: "Luke 24:12" },
  { text: "Behold, two of them were going that very day to a village named Emmaus, which was sixty stadia from Jerusalem.", reference: "Luke 24:13" },
  { text: "They talked with each other about all of these things which had happened.", reference: "Luke 24:14" },
  { text: "While they talked and questioned together, Jesus himself came near, and went with them.", reference: "Luke 24:15" },
  { text: "But their eyes were kept from recognizing him.", reference: "Luke 24:16" },
  { text: "He said to them, “What are you talking about as you walk, and are sad?”", reference: "Luke 24:17" },
  { text: "One of them, named Cleopas, answered him, “Are you the only stranger in Jerusalem who doesn’t know the things which have happened there in these days?”", reference: "Luke 24:18" },
  { text: "He said to them, “What things?” They said to him, “The things concerning Jesus, the Nazarene, who was a prophet mighty in deed and word before God and all the people;", reference: "Luke 24:19" },
  { text: "and how the chief priests and our rulers delivered him up to be condemned to death, and crucified him.", reference: "Luke 24:20" },
  { text: "But we were hoping that it was he who would redeem Israel. Yes, and besides all this, it is now the third day since these things happened.", reference: "Luke 24:21" },
  { text: "Also, certain women of our company amazed us, having arrived early at the tomb;", reference: "Luke 24:22" },
  { text: "and when they didn’t find his body, they came saying that they had also seen a vision of angels, who said that he was alive.", reference: "Luke 24:23" },
  { text: "Some of us went to the tomb, and found it just like the women had said, but they didn’t see him.”", reference: "Luke 24:24" },
  { text: "He said to them, “Foolish men, and slow of heart to believe in all that the prophets have spoken!", reference: "Luke 24:25" },
  { text: "Didn’t the Christ have to suffer these things and to enter into his glory?”", reference: "Luke 24:26" },
  { text: "Beginning from Moses and from all the prophets, he explained to them in all the Scriptures the things concerning himself.", reference: "Luke 24:27" },
  { text: "They came near to the village, where they were going, and he acted like he would go further.", reference: "Luke 24:28" },
  { text: "They urged him, saying, “Stay with us, for it is almost evening, and the day is almost over.” He went in to stay with them.", reference: "Luke 24:29" },
  { text: "When he had sat down at the table with them, he took the bread and gave thanks. Breaking it, he gave it to them.", reference: "Luke 24:30" },
  { text: "Their eyes were opened, and they recognized him, and he vanished out of their sight.", reference: "Luke 24:31" },
  { text: "They said to one another, “Weren’t our hearts burning within us, while he spoke to us along the way, and while he opened the Scriptures to us?”", reference: "Luke 24:32" },
  { text: "They rose up that very hour, returned to Jerusalem, and found the eleven gathered together, and those who were with them,", reference: "Luke 24:33" },
  { text: "saying, “The Lord is risen indeed, and has appeared to Simon!”", reference: "Luke 24:34" },
  { text: "They related the things that happened along the way, and how he was recognized by them in the breaking of the bread.", reference: "Luke 24:35" },
  { text: "As they said these things, Jesus himself stood among them, and said to them, “Peace be to you.”", reference: "Luke 24:36" },
  { text: "But they were terrified and filled with fear, and supposed that they had seen a spirit.", reference: "Luke 24:37" },
  { text: "He said to them, “Why are you troubled? Why do doubts arise in your hearts?", reference: "Luke 24:38" },
  { text: "See my hands and my feet, that it is truly me. Touch me and see, for a spirit doesn’t have flesh and bones, as you see that I have.”", reference: "Luke 24:39" },
  { text: "When he had said this, he showed them his hands and his feet.", reference: "Luke 24:40" },
  { text: "While they still didn’t believe for joy, and wondered, he said to them, “Do you have anything here to eat?”", reference: "Luke 24:41" },
  { text: "They gave him a piece of a broiled fish and some honeycomb.", reference: "Luke 24:42" },
  { text: "He said to them, “This is what I told you, while I was still with you, that all things which are written in the law of Moses, the prophets, and the psalms, concerning me must be fulfilled.”", reference: "Luke 24:44" },
  { text: "Then he opened their minds, that they might understand the Scriptures.", reference: "Luke 24:45" },
  { text: "He said to them, “Thus it is written, and thus it was necessary for the Christ to suffer and to rise from the dead the third day,", reference: "Luke 24:46" },
  { text: "and that repentance and remission of sins should be preached in his name to all the nations, beginning at Jerusalem.", reference: "Luke 24:47" },
  { text: "Behold, I send out the promise of my Father on you. But wait in the city of Jerusalem until you are clothed with power from on high.”", reference: "Luke 24:49" },
  { text: "He led them out as far as Bethany, and he lifted up his hands, and blessed them.", reference: "Luke 24:50" },
  { text: "While he blessed them, he withdrew from them, and was carried up into heaven.", reference: "Luke 24:51" },
  { text: "They worshiped him, and returned to Jerusalem with great joy,", reference: "Luke 24:52" },
  { text: "and were continually in the temple, praising and blessing God. Amen.", reference: "Luke 24:53" },
  { text: "Blessed is the man who doesn’t walk in the counsel of the wicked, nor stand on the path of sinners, nor sit in the seat of scoffers;", reference: "Psalms 1:1" },
  { text: "but his delight is in Yahweh’s law. On his law he meditates day and night.", reference: "Psalms 1:2" },
  { text: "He will be like a tree planted by the streams of water, that produces its fruit in its season, whose leaf also does not wither. Whatever he does shall prosper.", reference: "Psalms 1:3" },
  { text: "The wicked are not so, but are like the chaff which the wind drives away.", reference: "Psalms 1:4" },
  { text: "Therefore the wicked shall not stand in the judgment, nor sinners in the congregation of the righteous.", reference: "Psalms 1:5" },
  { text: "For Yahweh knows the way of the righteous, but the way of the wicked shall perish.", reference: "Psalms 1:6" },
  { text: "Why do the nations rage, and the peoples plot a vain thing?", reference: "Psalms 2:1" },
  { text: "The kings of the earth take a stand, and the rulers take counsel together, against Yahweh, and against his Anointed, saying,", reference: "Psalms 2:2" },
  { text: "“Let’s break their bonds apart, and cast their cords from us.”", reference: "Psalms 2:3" },
  { text: "He who sits in the heavens will laugh. The Lord will have them in derision.", reference: "Psalms 2:4" },
  { text: "Then he will speak to them in his anger, and terrify them in his wrath:", reference: "Psalms 2:5" },
  { text: "“Yet I have set my King on my holy hill of Zion.”", reference: "Psalms 2:6" },
  { text: "I will tell of the decree. Yahweh said to me, “You are my son. Today I have become your father.", reference: "Psalms 2:7" },
  { text: "Ask of me, and I will give the nations for your inheritance, the uttermost parts of the earth for your possession.", reference: "Psalms 2:8" },
  { text: "You shall break them with a rod of iron. You shall dash them in pieces like a potter’s vessel.”", reference: "Psalms 2:9" },
  { text: "Now therefore be wise, you kings. Be instructed, you judges of the earth.", reference: "Psalms 2:10" },
  { text: "Serve Yahweh with fear, and rejoice with trembling.", reference: "Psalms 2:11" },
  { text: "Give sincere homage to the Son, lest he be angry, and you perish on the way, for his wrath will soon be kindled. Blessed are all those who take refuge in him.", reference: "Psalms 2:12" },
  { text: "Yahweh, how my adversaries have increased! Many are those who rise up against me.", reference: "Psalms 3:1" },
  { text: "Many there are who say of my soul, “There is no help for him in God.” Selah.", reference: "Psalms 3:2" },
  { text: "But you, Yahweh, are a shield around me, my glory, and the one who lifts up my head.", reference: "Psalms 3:3" },
  { text: "I cry to Yahweh with my voice, and he answers me out of his holy hill. Selah.", reference: "Psalms 3:4" },
  { text: "I laid myself down and slept. I awakened; for Yahweh sustains me.", reference: "Psalms 3:5" },
  { text: "I will not be afraid of tens of thousands of people who have set themselves against me on every side.", reference: "Psalms 3:6" },
  { text: "Arise, Yahweh! Save me, my God! For you have struck all of my enemies on the cheek bone. You have broken the teeth of the wicked.", reference: "Psalms 3:7" },
  { text: "Salvation belongs to Yahweh. Your blessing be on your people. Selah.", reference: "Psalms 3:8" },
  { text: "Answer me when I call, God of my righteousness. Give me relief from my distress. Have mercy on me, and hear my prayer.", reference: "Psalms 4:1" },
  { text: "You sons of men, how long shall my glory be turned into dishonor? Will you love vanity, and seek after falsehood? Selah.", reference: "Psalms 4:2" },
  { text: "But know that Yahweh has set apart for himself him who is godly: Yahweh will hear when I call to him.", reference: "Psalms 4:3" },
  { text: "Stand in awe, and don’t sin. Search your own heart on your bed, and be still. Selah.", reference: "Psalms 4:4" },
  { text: "Offer the sacrifices of righteousness. Put your trust in Yahweh.", reference: "Psalms 4:5" },
  { text: "Many say, “Who will show us any good?” Yahweh, let the light of your face shine on us.", reference: "Psalms 4:6" },
  { text: "You have put gladness in my heart, more than when their grain and their new wine are increased.", reference: "Psalms 4:7" },
  { text: "In peace I will both lay myself down and sleep, for you, Yahweh alone, make me live in safety.", reference: "Psalms 4:8" },
  { text: "Give ear to my words, Yahweh. Consider my meditation.", reference: "Psalms 5:1" },
  { text: "Listen to the voice of my cry, my King and my God; for to you do I pray.", reference: "Psalms 5:2" },
  { text: "Yahweh, in the morning you shall hear my voice. In the morning I will lay my requests before you, and will watch expectantly.", reference: "Psalms 5:3" },
  { text: "For you are not a God who has pleasure in wickedness. Evil can’t live with you.", reference: "Psalms 5:4" },
  { text: "The arrogant shall not stand in your sight. You hate all workers of iniquity.", reference: "Psalms 5:5" },
  { text: "You will destroy those who speak lies. Yahweh abhors the bloodthirsty and deceitful man.", reference: "Psalms 5:6" },
  { text: "But as for me, in the abundance of your loving kindness I will come into your house. I will bow toward your holy temple in reverence of you.", reference: "Psalms 5:7" },
  { text: "Lead me, Yahweh, in your righteousness because of my enemies. Make your way straight before my face.", reference: "Psalms 5:8" },
  { text: "For there is no faithfulness in their mouth. Their heart is destruction. Their throat is an open tomb. They flatter with their tongue.", reference: "Psalms 5:9" },
  { text: "Hold them guilty, God. Let them fall by their own counsels; Thrust them out in the multitude of their transgressions, for they have rebelled against you.", reference: "Psalms 5:10" },
  { text: "But let all those who take refuge in you rejoice, Let them always shout for joy, because you defend them. Let them also who love your name be joyful in you.", reference: "Psalms 5:11" },
  { text: "For you will bless the righteous. Yahweh, you will surround him with favor as with a shield.", reference: "Psalms 5:12" },
  { text: "Yahweh, don’t rebuke me in your anger, neither discipline me in your wrath.", reference: "Psalms 6:1" },
  { text: "Have mercy on me, Yahweh, for I am faint. Yahweh, heal me, for my bones are troubled.", reference: "Psalms 6:2" },
  { text: "My soul is also in great anguish. But you, Yahweh—how long?", reference: "Psalms 6:3" },
  { text: "Return, Yahweh. Deliver my soul, and save me for your loving kindness’ sake.", reference: "Psalms 6:4" },
  { text: "For in death there is no memory of you. In Sheol, who shall give you thanks?", reference: "Psalms 6:5" },
  { text: "I am weary with my groaning. Every night I flood my bed. I drench my couch with my tears.", reference: "Psalms 6:6" },
  { text: "My eye wastes away because of grief. It grows old because of all my adversaries.", reference: "Psalms 6:7" },
  { text: "Depart from me, all you workers of iniquity, for Yahweh has heard the voice of my weeping.", reference: "Psalms 6:8" },
  { text: "Yahweh has heard my supplication. Yahweh accepts my prayer.", reference: "Psalms 6:9" },
  { text: "May all my enemies be ashamed and dismayed. They shall turn back, they shall be disgraced suddenly.", reference: "Psalms 6:10" },
  { text: "This is the third time I am coming to you. “At the mouth of two or three witnesses shall every word be established.”", reference: "2 Corinthians 13:1" },
  { text: "seeing that you seek a proof of Christ who speaks in me; who toward you is not weak, but is powerful in you.", reference: "2 Corinthians 13:3" },
  { text: "For he was crucified through weakness, yet he lives through the power of God. For we also are weak in him, but we will live with him through the power of God toward you.", reference: "2 Corinthians 13:4" },
  { text: "Examine your own selves, whether you are in the faith. Test your own selves. Or don’t you know as to your own selves, that Jesus Christ is in you?—unless indeed you are disqualified.", reference: "2 Corinthians 13:5" },
  { text: "But I hope that you will know that we aren’t disqualified.", reference: "2 Corinthians 13:6" },
  { text: "Now I pray to God that you do no evil; not that we may appear approved, but that you may do that which is honorable, though we are as reprobate.", reference: "2 Corinthians 13:7" },
  { text: "For we can do nothing against the truth, but for the truth.", reference: "2 Corinthians 13:8" },
  { text: "For we rejoice when we are weak and you are strong. And this we also pray for, even your perfecting.", reference: "2 Corinthians 13:9" },
  { text: "For this cause I write these things while absent, that I may not deal sharply when present, according to the authority which the Lord gave me for building up, and not for tearing down.", reference: "2 Corinthians 13:10" },
  { text: "Finally, brothers, rejoice. Be perfected, be comforted, be of the same mind, live in peace, and the God of love and peace will be with you.", reference: "2 Corinthians 13:11" },
  { text: "The grace of the Lord Jesus Christ, God’s love, and the fellowship of the Holy Spirit, be with you all. Amen.", reference: "2 Corinthians 13:14" },
  { text: "Paul, an apostle of Christ Jesus through the will of God, to the saints who are at Ephesus, and the faithful in Christ Jesus:", reference: "Ephesians 1:1" },
  { text: "Grace to you and peace from God our Father and the Lord Jesus Christ.", reference: "Ephesians 1:2" },
  { text: "Blessed be the God and Father of our Lord Jesus Christ, who has blessed us with every spiritual blessing in the heavenly places in Christ;", reference: "Ephesians 1:3" },
  { text: "even as he chose us in him before the foundation of the world, that we would be holy and without defect before him in love;", reference: "Ephesians 1:4" },
  { text: "having predestined us for adoption as children through Jesus Christ to himself, according to the good pleasure of his desire,", reference: "Ephesians 1:5" },
  { text: "to the praise of the glory of his grace, by which he freely gave us favor in the Beloved,", reference: "Ephesians 1:6" },
  { text: "in whom we have our redemption through his blood, the forgiveness of our trespasses, according to the riches of his grace,", reference: "Ephesians 1:7" },
  { text: "which he made to abound toward us in all wisdom and prudence,", reference: "Ephesians 1:8" },
  { text: "making known to us the mystery of his will, according to his good pleasure which he purposed in him", reference: "Ephesians 1:9" },
  { text: "to an administration of the fullness of the times, to sum up all things in Christ, the things in the heavens, and the things on the earth, in him;", reference: "Ephesians 1:10" },
  { text: "in whom also we were assigned an inheritance, having been foreordained according to the purpose of him who does all things after the counsel of his will;", reference: "Ephesians 1:11" },
  { text: "to the end that we should be to the praise of his glory, we who had before hoped in Christ.", reference: "Ephesians 1:12" },
  { text: "In him you also, having heard the word of the truth, the Good News of your salvation—in whom, having also believed, you were sealed with the promised Holy Spirit,", reference: "Ephesians 1:13" },
  { text: "who is a pledge of our inheritance, to the redemption of God’s own possession, to the praise of his glory.", reference: "Ephesians 1:14" },
  { text: "For this cause I also, having heard of the faith in the Lord Jesus which is among you, and the love which you have toward all the saints,", reference: "Ephesians 1:15" },
  { text: "don’t cease to give thanks for you, making mention of you in my prayers,", reference: "Ephesians 1:16" },
  { text: "that the God of our Lord Jesus Christ, the Father of glory, may give to you a spirit of wisdom and revelation in the knowledge of him;", reference: "Ephesians 1:17" },
  { text: "having the eyes of your hearts enlightened, that you may know what is the hope of his calling, and what are the riches of the glory of his inheritance in the saints,", reference: "Ephesians 1:18" },
  { text: "and what is the exceeding greatness of his power toward us who believe, according to that working of the strength of his might", reference: "Ephesians 1:19" },
  { text: "which he worked in Christ, when he raised him from the dead, and made him to sit at his right hand in the heavenly places,", reference: "Ephesians 1:20" },
  { text: "far above all rule, and authority, and power, and dominion, and every name that is named, not only in this age, but also in that which is to come.", reference: "Ephesians 1:21" },
  { text: "He put all things in subjection under his feet, and gave him to be head over all things for the assembly,", reference: "Ephesians 1:22" },
  { text: "which is his body, the fullness of him who fills all in all.", reference: "Ephesians 1:23" },
  { text: "You were made alive when you were dead in transgressions and sins,", reference: "Ephesians 2:1" },
  { text: "in which you once walked according to the course of this world, according to the prince of the power of the air, the spirit who now works in the children of disobedience;", reference: "Ephesians 2:2" },
  { text: "among whom we also all once lived in the lusts of our flesh, doing the desires of the flesh and of the mind, and were by nature children of wrath, even as the rest.", reference: "Ephesians 2:3" },
  { text: "But God, being rich in mercy, for his great love with which he loved us,", reference: "Ephesians 2:4" },
  { text: "even when we were dead through our trespasses, made us alive together with Christ (by grace you have been saved),", reference: "Ephesians 2:5" },
  { text: "and raised us up with him, and made us to sit with him in the heavenly places in Christ Jesus,", reference: "Ephesians 2:6" },
  { text: "that in the ages to come he might show the exceeding riches of his grace in kindness toward us in Christ Jesus;", reference: "Ephesians 2:7" },
  { text: "for by grace you have been saved through faith, and that not of yourselves; it is the gift of God,", reference: "Ephesians 2:8" },
  { text: "For we are his workmanship, created in Christ Jesus for good works, which God prepared before that we would walk in them.", reference: "Ephesians 2:10" },
  { text: "Therefore remember that once you, the Gentiles in the flesh, who are called “uncircumcision” by that which is called “circumcision”, (in the flesh, made by hands);", reference: "Ephesians 2:11" },
  { text: "that you were at that time separate from Christ, alienated from the commonwealth of Israel, and strangers from the covenants of the promise, having no hope and without God in the world.", reference: "Ephesians 2:12" },
  { text: "But now in Christ Jesus you who once were far off are made near in the blood of Christ.", reference: "Ephesians 2:13" },
  { text: "For he is our peace, who made both one, and broke down the middle wall of partition,", reference: "Ephesians 2:14" },
  { text: "having abolished in his flesh the hostility, the law of commandments contained in ordinances, that he might create in himself one new man of the two, making peace;", reference: "Ephesians 2:15" },
  { text: "and might reconcile them both in one body to God through the cross, having killed the hostility thereby.", reference: "Ephesians 2:16" },
  { text: "He came and preached peace to you who were far off and to those who were near.", reference: "Ephesians 2:17" },
  { text: "For through him we both have our access in one Spirit to the Father.", reference: "Ephesians 2:18" },
  { text: "So then you are no longer strangers and foreigners, but you are fellow citizens with the saints, and of the household of God,", reference: "Ephesians 2:19" },
  { text: "being built on the foundation of the apostles and prophets, Christ Jesus himself being the chief cornerstone;", reference: "Ephesians 2:20" },
  { text: "in whom the whole building, fitted together, grows into a holy temple in the Lord;", reference: "Ephesians 2:21" },
  { text: "in whom you also are built together for a habitation of God in the Spirit.", reference: "Ephesians 2:22" },
  { text: "For this cause I, Paul, am the prisoner of Christ Jesus on behalf of you Gentiles,", reference: "Ephesians 3:1" },
  { text: "if it is so that you have heard of the administration of that grace of God which was given me toward you;", reference: "Ephesians 3:2" },
  { text: "how that by revelation the mystery was made known to me, as I wrote before in few words,", reference: "Ephesians 3:3" },
  { text: "by which, when you read, you can perceive my understanding in the mystery of Christ;", reference: "Ephesians 3:4" },
  { text: "which in other generations was not made known to the children of men, as it has now been revealed to his holy apostles and prophets in the Spirit;", reference: "Ephesians 3:5" },
  { text: "that the Gentiles are fellow heirs, and fellow members of the body, and fellow partakers of his promise in Christ Jesus through the Good News,", reference: "Ephesians 3:6" },
  { text: "of which I was made a servant, according to the gift of that grace of God which was given me according to the working of his power.", reference: "Ephesians 3:7" },
  { text: "To me, the very least of all saints, was this grace given, to preach to the Gentiles the unsearchable riches of Christ,", reference: "Ephesians 3:8" },
  { text: "and to make all men see what is the administration of the mystery which for ages has been hidden in God, who created all things through Jesus Christ;", reference: "Ephesians 3:9" },
  { text: "to the intent that now through the assembly the manifold wisdom of God might be made known to the principalities and the powers in the heavenly places,", reference: "Ephesians 3:10" },
  { text: "according to the eternal purpose which he purposed in Christ Jesus our Lord;", reference: "Ephesians 3:11" },
  { text: "in whom we have boldness and access in confidence through our faith in him.", reference: "Ephesians 3:12" },
  { text: "Therefore I ask that you may not lose heart at my troubles for you, which are your glory.", reference: "Ephesians 3:13" },
  { text: "For this cause, I bow my knees to the Father of our Lord Jesus Christ,", reference: "Ephesians 3:14" },
  { text: "from whom every family in heaven and on earth is named,", reference: "Ephesians 3:15" },
  { text: "that he would grant you, according to the riches of his glory, that you may be strengthened with power through his Spirit in the inward man;", reference: "Ephesians 3:16" },
  { text: "that Christ may dwell in your hearts through faith; to the end that you, being rooted and grounded in love,", reference: "Ephesians 3:17" },
  { text: "may be strengthened to comprehend with all the saints what is the width and length and height and depth,", reference: "Ephesians 3:18" },
  { text: "and to know Christ’s love which surpasses knowledge, that you may be filled with all the fullness of God.", reference: "Ephesians 3:19" },
  { text: "Now to him who is able to do exceedingly abundantly above all that we ask or think, according to the power that works in us,", reference: "Ephesians 3:20" },
  { text: "to him be the glory in the assembly and in Christ Jesus to all generations forever and ever. Amen.", reference: "Ephesians 3:21" },
  { text: "I therefore, the prisoner in the Lord, beg you to walk worthily of the calling with which you were called,", reference: "Ephesians 4:1" },
  { text: "with all lowliness and humility, with patience, bearing with one another in love;", reference: "Ephesians 4:2" },
  { text: "being eager to keep the unity of the Spirit in the bond of peace.", reference: "Ephesians 4:3" },
  { text: "There is one body, and one Spirit, even as you also were called in one hope of your calling;", reference: "Ephesians 4:4" },
  { text: "one God and Father of all, who is over all, and through all, and in us all.", reference: "Ephesians 4:6" },
  { text: "But to each one of us was the grace given according to the measure of the gift of Christ.", reference: "Ephesians 4:7" },
  { text: "Therefore he says, “When he ascended on high, he led captivity captive, and gave gifts to men.”", reference: "Ephesians 4:8" },
  { text: "Now this, “He ascended”, what is it but that he also first descended into the lower parts of the earth?", reference: "Ephesians 4:9" },
  { text: "He who descended is the one who also ascended far above all the heavens, that he might fill all things.", reference: "Ephesians 4:10" },
  { text: "He gave some to be apostles; and some, prophets; and some, evangelists; and some, shepherds and teachers;", reference: "Ephesians 4:11" },
  { text: "for the perfecting of the saints, to the work of serving, to the building up of the body of Christ;", reference: "Ephesians 4:12" },
  { text: "until we all attain to the unity of the faith, and of the knowledge of the Son of God, to a full grown man, to the measure of the stature of the fullness of Christ;", reference: "Ephesians 4:13" },
  { text: "that we may no longer be children, tossed back and forth and carried about with every wind of doctrine, by the trickery of men, in craftiness, after the wiles of error;", reference: "Ephesians 4:14" },
  { text: "but speaking truth in love, we may grow up in all things into him, who is the head, Christ;", reference: "Ephesians 4:15" },
  { text: "This I say therefore, and testify in the Lord, that you no longer walk as the rest of the Gentiles also walk, in the futility of their mind,", reference: "Ephesians 4:17" },
  { text: "being darkened in their understanding, alienated from the life of God, because of the ignorance that is in them, because of the hardening of their hearts;", reference: "Ephesians 4:18" },
  { text: "who having become callous gave themselves up to lust, to work all uncleanness with greediness.", reference: "Ephesians 4:19" },
  { text: "if indeed you heard him, and were taught in him, even as truth is in Jesus:", reference: "Ephesians 4:21" },
  { text: "that you put away, as concerning your former way of life, the old man, that grows corrupt after the lusts of deceit;", reference: "Ephesians 4:22" },
  { text: "and that you be renewed in the spirit of your mind,", reference: "Ephesians 4:23" },
  { text: "and put on the new man, who in the likeness of God has been created in righteousness and holiness of truth.", reference: "Ephesians 4:24" },
  { text: "Therefore putting away falsehood, speak truth each one with his neighbor. For we are members of one another.", reference: "Ephesians 4:25" },
  { text: "“Be angry, and don’t sin.” Don’t let the sun go down on your wrath,", reference: "Ephesians 4:26" },
  { text: "Let him who stole steal no more; but rather let him labor, producing with his hands something that is good, that he may have something to give to him who has need.", reference: "Ephesians 4:28" },
  { text: "Let no corrupt speech proceed out of your mouth, but only what is good for building others up as the need may be, that it may give grace to those who hear.", reference: "Ephesians 4:29" },
  { text: "Don’t grieve the Holy Spirit of God, in whom you were sealed for the day of redemption.", reference: "Ephesians 4:30" },
  { text: "Let all bitterness, wrath, anger, outcry, and slander, be put away from you, with all malice.", reference: "Ephesians 4:31" },
  { text: "And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.", reference: "Ephesians 4:32" },
  { text: "Be therefore imitators of God, as beloved children.", reference: "Ephesians 5:1" },
  { text: "Walk in love, even as Christ also loved you, and gave himself up for us, an offering and a sacrifice to God for a sweet-smelling fragrance.", reference: "Ephesians 5:2" },
  { text: "But sexual immorality, and all uncleanness, or covetousness, let it not even be mentioned among you, as becomes saints;", reference: "Ephesians 5:3" },
  { text: "nor filthiness, nor foolish talking, nor jesting, which are not appropriate; but rather giving of thanks.", reference: "Ephesians 5:4" },
  { text: "Know this for sure, that no sexually immoral person, nor unclean person, nor covetous man, who is an idolater, has any inheritance in the Kingdom of Christ and God.", reference: "Ephesians 5:5" },
  { text: "Let no one deceive you with empty words. For because of these things, the wrath of God comes on the children of disobedience.", reference: "Ephesians 5:6" },
  { text: "For you were once darkness, but are now light in the Lord. Walk as children of light,", reference: "Ephesians 5:8" },
  { text: "for the fruit of the Spirit is in all goodness and righteousness and truth,", reference: "Ephesians 5:9" },
  { text: "Have no fellowship with the unfruitful deeds of darkness, but rather even reprove them.", reference: "Ephesians 5:11" },
  { text: "For the things which are done by them in secret, it is a shame even to speak of.", reference: "Ephesians 5:12" },
  { text: "But all things, when they are reproved, are revealed by the light, for everything that reveals is light.", reference: "Ephesians 5:13" },
  { text: "Therefore he says, “Awake, you who sleep, and arise from the dead, and Christ will shine on you.”", reference: "Ephesians 5:14" },
  { text: "Therefore watch carefully how you walk, not as unwise, but as wise;", reference: "Ephesians 5:15" },
  { text: "redeeming the time, because the days are evil.", reference: "Ephesians 5:16" },
  { text: "Therefore don’t be foolish, but understand what the will of the Lord is.", reference: "Ephesians 5:17" },
  { text: "Don’t be drunken with wine, in which is dissipation, but be filled with the Spirit,", reference: "Ephesians 5:18" },
  { text: "speaking to one another in psalms, hymns, and spiritual songs; singing, and making melody in your heart to the Lord;", reference: "Ephesians 5:19" },
  { text: "giving thanks always concerning all things in the name of our Lord Jesus Christ, to God, even the Father;", reference: "Ephesians 5:20" },
  { text: "subjecting yourselves to one another in the fear of Christ.", reference: "Ephesians 5:21" },
  { text: "Wives, be subject to your own husbands, as to the Lord.", reference: "Ephesians 5:22" },
  { text: "For the husband is the head of the wife, as Christ also is the head of the assembly, being himself the savior of the body.", reference: "Ephesians 5:23" },
  { text: "But as the assembly is subject to Christ, so let the wives also be to their own husbands in everything.", reference: "Ephesians 5:24" },
  { text: "Husbands, love your wives, even as Christ also loved the assembly, and gave himself up for it;", reference: "Ephesians 5:25" },
  { text: "that he might sanctify it, having cleansed it by the washing of water with the word,", reference: "Ephesians 5:26" },
  { text: "that he might present the assembly to himself gloriously, not having spot or wrinkle or any such thing; but that it should be holy and without defect.", reference: "Ephesians 5:27" },
  { text: "Even so husbands also ought to love their own wives as their own bodies. He who loves his own wife loves himself.", reference: "Ephesians 5:28" },
  { text: "For no man ever hated his own flesh; but nourishes and cherishes it, even as the Lord also does the assembly;", reference: "Ephesians 5:29" },
  { text: "because we are members of his body, of his flesh and bones.", reference: "Ephesians 5:30" },
  { text: "“For this cause a man will leave his father and mother, and will be joined to his wife. The two will become one flesh.”", reference: "Ephesians 5:31" },
  { text: "This mystery is great, but I speak concerning Christ and of the assembly.", reference: "Ephesians 5:32" },
  { text: "Nevertheless each of you must also love his own wife even as himself; and let the wife see that she respects her husband.", reference: "Ephesians 5:33" },
  { text: "Children, obey your parents in the Lord, for this is right.", reference: "Ephesians 6:1" },
  { text: "“Honor your father and mother,” which is the first commandment with a promise:", reference: "Ephesians 6:2" },
  { text: "“that it may be well with you, and you may live long on the earth.”", reference: "Ephesians 6:3" },
  { text: "You fathers, don’t provoke your children to wrath, but nurture them in the discipline and instruction of the Lord.", reference: "Ephesians 6:4" },
  { text: "Servants, be obedient to those who according to the flesh are your masters, with fear and trembling, in singleness of your heart, as to Christ;", reference: "Ephesians 6:5" },
  { text: "not in the way of service only when eyes are on you, as men pleasers; but as servants of Christ, doing the will of God from the heart;", reference: "Ephesians 6:6" },
  { text: "with good will doing service, as to the Lord, and not to men;", reference: "Ephesians 6:7" },
  { text: "knowing that whatever good thing each one does, he will receive the same again from the Lord, whether he is bound or free.", reference: "Ephesians 6:8" },
  { text: "You masters, do the same things to them, and give up threatening, knowing that he who is both their Master and yours is in heaven, and there is no partiality with him.", reference: "Ephesians 6:9" },
  { text: "Finally, be strong in the Lord, and in the strength of his might.", reference: "Ephesians 6:10" },
  { text: "Put on the whole armor of God, that you may be able to stand against the wiles of the devil.", reference: "Ephesians 6:11" },
  { text: "Therefore put on the whole armor of God, that you may be able to withstand in the evil day, and, having done all, to stand.", reference: "Ephesians 6:13" },
  { text: "Stand therefore, having the utility belt of truth buckled around your waist, and having put on the breastplate of righteousness,", reference: "Ephesians 6:14" },
  { text: "and having fitted your feet with the preparation of the Good News of peace;", reference: "Ephesians 6:15" },
  { text: "above all, taking up the shield of faith, with which you will be able to quench all the fiery darts of the evil one.", reference: "Ephesians 6:16" },
  { text: "And take the helmet of salvation, and the sword of the Spirit, which is the word of God;", reference: "Ephesians 6:17" },
  { text: "with all prayer and requests, praying at all times in the Spirit, and being watchful to this end in all perseverance and requests for all the saints:", reference: "Ephesians 6:18" },
  { text: "on my behalf, that utterance may be given to me in opening my mouth, to make known with boldness the mystery of the Good News,", reference: "Ephesians 6:19" },
  { text: "for which I am an ambassador in chains; that in it I may speak boldly, as I ought to speak.", reference: "Ephesians 6:20" },
  { text: "But that you also may know my affairs, how I am doing, Tychicus, the beloved brother and faithful servant in the Lord, will make known to you all things;", reference: "Ephesians 6:21" },
  { text: "whom I have sent to you for this very purpose, that you may know our state, and that he may comfort your hearts.", reference: "Ephesians 6:22" },
  { text: "Peace be to the brothers, and love with faith, from God the Father and the Lord Jesus Christ.", reference: "Ephesians 6:23" },
  { text: "Grace be with all those who love our Lord Jesus Christ with incorruptible love. Amen.", reference: "Ephesians 6:24" },
  { text: "Paul, an apostle of Jesus Christ according to the commandment of God our Savior and the Lord Jesus Christ our hope;", reference: "1 Timothy 1:1" },
  { text: "to Timothy, my true child in faith: Grace, mercy, and peace, from God our Father and Christ Jesus our Lord.", reference: "1 Timothy 1:2" },
  { text: "As I urged you when I was going into Macedonia, stay at Ephesus that you might command certain men not to teach a different doctrine,", reference: "1 Timothy 1:3" },
  { text: "and not to pay attention to myths and endless genealogies, which cause disputes, rather than God’s stewardship, which is in faith—", reference: "1 Timothy 1:4" },
  { text: "but the goal of this command is love, out of a pure heart and a good conscience and sincere faith;", reference: "1 Timothy 1:5" },
  { text: "from which things some, having missed the mark, have turned away to vain talking;", reference: "1 Timothy 1:6" },
  { text: "desiring to be teachers of the law, though they understand neither what they say, nor about what they strongly affirm.", reference: "1 Timothy 1:7" },
  { text: "But we know that the law is good, if a person uses it lawfully,", reference: "1 Timothy 1:8" },
  { text: "for the sexually immoral, for homosexuals, for slave-traders, for liars, for perjurers, and for any other thing contrary to the sound doctrine;", reference: "1 Timothy 1:10" },
  { text: "according to the Good News of the glory of the blessed God, which was committed to my trust.", reference: "1 Timothy 1:11" },
  { text: "And I thank him who enabled me, Christ Jesus our Lord, because he counted me faithful, appointing me to service;", reference: "1 Timothy 1:12" },
  { text: "although I was before a blasphemer, a persecutor, and insolent. However, I obtained mercy, because I did it ignorantly in unbelief.", reference: "1 Timothy 1:13" },
  { text: "The grace of our Lord abounded exceedingly with faith and love which is in Christ Jesus.", reference: "1 Timothy 1:14" },
  { text: "The saying is faithful and worthy of all acceptance, that Christ Jesus came into the world to save sinners; of whom I am chief.", reference: "1 Timothy 1:15" },
  { text: "However, for this cause I obtained mercy, that in me first, Jesus Christ might display all his patience, for an example of those who were going to believe in him for eternal life.", reference: "1 Timothy 1:16" },
  { text: "Now to the King eternal, immortal, invisible, to God who alone is wise, be honor and glory forever and ever. Amen.", reference: "1 Timothy 1:17" },
  { text: "This instruction I commit to you, my child Timothy, according to the prophecies which were given to you before, that by them you may wage the good warfare;", reference: "1 Timothy 1:18" },
  { text: "holding faith and a good conscience; which some having thrust away made a shipwreck concerning the faith;", reference: "1 Timothy 1:19" },
  { text: "of whom are Hymenaeus and Alexander; whom I delivered to Satan, that they might be taught not to blaspheme.", reference: "1 Timothy 1:20" },
  { text: "I exhort therefore, first of all, that petitions, prayers, intercessions, and givings of thanks, be made for all men:", reference: "1 Timothy 2:1" },
  { text: "for kings and all who are in high places; that we may lead a tranquil and quiet life in all godliness and reverence.", reference: "1 Timothy 2:2" },
  { text: "For this is good and acceptable in the sight of God our Savior;", reference: "1 Timothy 2:3" },
  { text: "who desires all people to be saved and come to full knowledge of the truth.", reference: "1 Timothy 2:4" },
  { text: "For there is one God, and one mediator between God and men, the man Christ Jesus,", reference: "1 Timothy 2:5" },
  { text: "who gave himself as a ransom for all; the testimony in its own times;", reference: "1 Timothy 2:6" },
  { text: "to which I was appointed a preacher and an apostle (I am telling the truth in Christ, not lying), a teacher of the Gentiles in faith and truth.", reference: "1 Timothy 2:7" },
  { text: "I desire therefore that the men in every place pray, lifting up holy hands without anger and doubting.", reference: "1 Timothy 2:8" },
  { text: "In the same way, that women also adorn themselves in decent clothing, with modesty and propriety; not just with braided hair, gold, pearls, or expensive clothing;", reference: "1 Timothy 2:9" },
  { text: "but (which becomes women professing godliness) with good works.", reference: "1 Timothy 2:10" },
  { text: "Let a woman learn in quietness with full submission.", reference: "1 Timothy 2:11" },
  { text: "But I don’t permit a woman to teach, nor to exercise authority over a man, but to be in quietness.", reference: "1 Timothy 2:12" },
  { text: "Adam wasn’t deceived, but the woman, being deceived, has fallen into disobedience;", reference: "1 Timothy 2:14" },
  { text: "but she will be saved through her childbearing, if they continue in faith, love, and sanctification with sobriety.", reference: "1 Timothy 2:15" },
];
